// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "../core/RovifyToken.sol";

/**
 * @title Burn Mechanism - Automated Token Burning
 * @dev automated burning of platform fees
 */
contract BurnMechanism is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ===== ROLES =====
    bytes32 public constant BURN_MANAGER_ROLE = keccak256("BURN_MANAGER_ROLE");
    bytes32 public constant CONFIG_ROLE = keccak256("CONFIG_ROLE");

    RovifyToken public immutable token;

    // ===== CONFIG =====
    struct BurnConfiguration {
        uint128 totalBurned; // Total tokens burned
        uint128 feesCollected; // Total fees collected
        uint64 lastBurnTime; // Last burn timestamp
        uint32 burnInterval; // Burn frequency (seconds)
        uint16 burnPercentage; // Burn percentage (basis points)
        uint16 minBurnThousands; // Minimum burn (in thousands of tokens)
        bool autoBurnEnabled; // Auto-burn toggle
        bool emergencyStop; // Emergency stop switch
    }

    BurnConfiguration public config;

    // ===== METRICS =====
    uint256 public burnEvents;
    uint256 public avgBurnAmount;

    // ===== EVENTS =====
    event AutoBurnExecuted(uint256 amount, uint256 timestamp, uint256 gasUsed);
    event BurnConfigurationUpdated(uint256 interval, uint256 percentage);
    event EmergencyStopToggled(bool enabled);

    constructor(address _token, address _admin) {
        token = RovifyToken(_token);

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(BURN_MANAGER_ROLE, _admin);
        _grantRole(CONFIG_ROLE, _admin);

        // Initialize with gas-efficient defaults
        config = BurnConfiguration({
            totalBurned: 0,
            feesCollected: 0,
            lastBurnTime: uint64(block.timestamp),
            burnInterval: 7 days,
            burnPercentage: 2500, // 25%
            minBurnThousands: 1000, // 1M tokens
            autoBurnEnabled: true,
            emergencyStop: false
        });
    }

    /**
     * @dev auto-burn execution
     */
    function executeAutoBurn() external nonReentrant returns (uint256 burnAmount) {
        require(config.autoBurnEnabled && !config.emergencyStop, "Auto-burn disabled");
        require(block.timestamp >= config.lastBurnTime + config.burnInterval, "Too early");

        uint256 gasStart = gasleft();
        uint256 contractBalance = token.balanceOf(address(this));
        uint256 minBurn = uint256(config.minBurnThousands) * 1000 * 10 ** 18;

        require(contractBalance >= minBurn, "Below minimum threshold");

        // Calculate burn amount with unchecked math (safe with validated inputs)
        unchecked {
            burnAmount = (contractBalance * config.burnPercentage) / 10000;

            // Update configuration in single SSTORE
            config.totalBurned += uint128(burnAmount);
            config.lastBurnTime = uint64(block.timestamp);

            // Update metrics
            burnEvents += 1;
            avgBurnAmount = (avgBurnAmount * (burnEvents - 1) + burnAmount) / burnEvents;
        }

        // Execute burn
        token.burnTokens(burnAmount);

        // Transfer remaining fees to treasury with unchecked math
        uint256 remainingFees = contractBalance - burnAmount;
        if (remainingFees > 0) {
            IERC20(address(token)).safeTransfer(token.treasury(), remainingFees);
            unchecked {
                config.feesCollected += uint128(remainingFees);
            }
        }

        uint256 gasUsed = gasStart - gasleft();
        emit AutoBurnExecuted(burnAmount, block.timestamp, gasUsed);
    }

    /**
     * @dev Batch update configuration (single transaction)
     */
    function updateConfigurationBatch(
        uint32 interval,
        uint16 percentage,
        uint16 minThousands,
        bool autoEnabled
    ) external onlyRole(CONFIG_ROLE) {
        require(percentage <= 5000, "Max 50%");
        require(interval >= 1 days, "Min 1 day");

        config.burnInterval = interval;
        config.burnPercentage = percentage;
        config.minBurnThousands = minThousands;
        config.autoBurnEnabled = autoEnabled;

        emit BurnConfigurationUpdated(interval, percentage);
    }

    /**
     * @dev View functions
     */
    function canExecuteBurn() external view returns (bool executable, uint256 nextBurnTime, uint256 burnAmount) {
        nextBurnTime = config.lastBurnTime + config.burnInterval;
        executable = block.timestamp >= nextBurnTime && config.autoBurnEnabled && !config.emergencyStop;

        if (executable) {
            uint256 balance = token.balanceOf(address(this));
            uint256 minBurn = uint256(config.minBurnThousands) * 1000 * 10 ** 18;

            if (balance >= minBurn) {
                unchecked {
                    burnAmount = (balance * config.burnPercentage) / 10000;
                }
            } else {
                executable = false;
            }
        }
    }

    /**
     * @dev Gas-efficient metrics getter
     */
    function getBurnMetrics()
        external
        view
        returns (
            uint256 totalBurned,
            uint256 feesCollected,
            uint256 burnEvents_,
            uint256 avgBurnAmount_,
            uint256 lastBurnTime,
            bool autoBurnEnabled
        )
    {
        return (
            config.totalBurned,
            config.feesCollected,
            burnEvents,
            avgBurnAmount,
            config.lastBurnTime,
            config.autoBurnEnabled
        );
    }
}

contracts/core/RovifyToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title Rovify Token (RVFY) - Core ERC20 Token
 * @dev ERC20 token with burn mechanism and RBAC
 * @author Rovify Team
 */
contract RovifyToken is ERC20, ERC20Burnable, Pausable, AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ===== ROLES =====
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");
    bytes32 public constant GOVERNANCE_ROLE = keccak256("GOVERNANCE_ROLE");
    bytes32 public constant TREASURY_ROLE = keccak256("TREASURY_ROLE");

    // ===== PACKED STORAGE =====
    struct TokenMetrics {
        uint128 totalBurned; // Total tokens burned
        uint128 maxSupply; // Maximum token supply
        uint64 lastBurnTime; // Last burn execution
        uint32 burnCount; // Number of burns executed
        bool emergencyMode; // Emergency pause state
    }

    TokenMetrics public metrics;

    // ===== CONSTANTS =====
    uint256 private constant INITIAL_SUPPLY = 7_500_000_000 * 10 ** 18; // 7.5B
    uint256 private constant TREASURY_PERCENT = 40;
    uint256 private constant ECOSYSTEM_PERCENT = 30;
    uint256 private constant TEAM_PERCENT = 20;
    uint256 private constant LIQUIDITY_PERCENT = 10;

    // ===== ADDRESSES =====
    address public immutable treasury;
    address public immutable ecosystem;
    address public immutable teamVesting;
    address public burnContract;

    // ===== EVENTS =====
    event TokensBurned(uint256 amount, uint256 newTotal);
    event BurnContractUpdated(address indexed oldContract, address indexed newContract);
    event EmergencyModeToggled(bool enabled);

    // ===== MODIFIERS =====
    modifier notInEmergency() {
        require(!metrics.emergencyMode, "Emergency mode active");
        _;
    }

    modifier validAddress(address addr) {
        require(addr != address(0), "Zero address");
        _;
    }

    constructor(
        address _treasury,
        address _ecosystem,
        address _teamVesting,
        address _admin
    )
        ERC20("Rovify Token", "RVFY")
        validAddress(_treasury)
        validAddress(_ecosystem)
        validAddress(_teamVesting)
        validAddress(_admin)
    {
        treasury = _treasury;
        ecosystem = _ecosystem;
        teamVesting = _teamVesting;

        // Initialize metrics (single SSTORE)
        metrics = TokenMetrics({
            totalBurned: 0,
            maxSupply: uint128(INITIAL_SUPPLY),
            lastBurnTime: uint64(block.timestamp),
            burnCount: 0,
            emergencyMode: false
        });

        // Setup roles
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(GOVERNANCE_ROLE, _admin);
        _grantRole(TREASURY_ROLE, _treasury);
        _grantRole(PAUSER_ROLE, _admin);

        // init distribution
        unchecked {
            uint256 treasuryAmount = (INITIAL_SUPPLY * TREASURY_PERCENT) / 100;
            uint256 ecosystemAmount = (INITIAL_SUPPLY * ECOSYSTEM_PERCENT) / 100;
            uint256 teamAmount = (INITIAL_SUPPLY * TEAM_PERCENT) / 100;
            uint256 liquidityAmount = INITIAL_SUPPLY - treasuryAmount - ecosystemAmount - teamAmount;

            _mint(_treasury, treasuryAmount);
            _mint(_ecosystem, ecosystemAmount);
            _mint(_teamVesting, teamAmount);
            _mint(_admin, liquidityAmount);
        }
    }

    /**
     * @dev burn function with unchecked math
     */
    function burnTokens(uint256 amount) external onlyRole(BURNER_ROLE) notInEmergency nonReentrant {
        require(amount > 0, "Zero amount");
        require(balanceOf(address(this)) >= amount, "Insufficient balance");

        // Safe to use unchecked - we verified amount > 0 and sufficient balance
        unchecked {
            metrics.totalBurned += uint128(amount);
            metrics.burnCount += 1;
            metrics.lastBurnTime = uint64(block.timestamp);
        }

        _burn(address(this), amount);
        emit TokensBurned(amount, metrics.totalBurned);
    }

    /**
     * @dev Batch operations
     */
    function batchTransfer(address[] calldata recipients, uint256[] calldata amounts) external notInEmergency {
        require(recipients.length == amounts.length, "Array length mismatch");
        require(recipients.length <= 100, "Too many recipients"); // Gas limit protection

        uint256 totalAmount;

        // Calculate total in unchecked block (safe with length limit)
        unchecked {
            for (uint256 i = 0; i < recipients.length; ++i) {
                totalAmount += amounts[i];
            }
        }

        require(balanceOf(msg.sender) >= totalAmount, "Insufficient balance");

        // Execute transfers
        for (uint256 i = 0; i < recipients.length; ) {
            _transfer(msg.sender, recipients[i], amounts[i]);
            unchecked {
                ++i;
            } // Safe increment
        }
    }

    /**
     * @dev Set burn contract with role-based access
     */
    function setBurnContract(address _burnContract) external onlyRole(GOVERNANCE_ROLE) validAddress(_burnContract) {
        address oldContract = burnContract;
        burnContract = _burnContract;

        // Update roles atomically
        if (oldContract != address(0)) {
            _revokeRole(BURNER_ROLE, oldContract);
        }
        _grantRole(BURNER_ROLE, _burnContract);

        emit BurnContractUpdated(oldContract, _burnContract);
    }

    /**
     * @dev Emergency controls with proper role management
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    function toggleEmergencyMode() external onlyRole(GOVERNANCE_ROLE) {
        metrics.emergencyMode = !metrics.emergencyMode;
        emit EmergencyModeToggled(metrics.emergencyMode);
    }

    /**
     * @dev Gas-efficient batch getter
     */
    function getTokenMetrics()
        external
        view
        returns (
            uint256 currentSupply,
            uint256 totalBurned,
            uint256 burnCount,
            uint256 lastBurnTime,
            bool emergencyMode
        )
    {
        return (totalSupply(), metrics.totalBurned, metrics.burnCount, metrics.lastBurnTime, metrics.emergencyMode);
    }

    /**
     * @dev Override transfer with optimizations
     */
    function _update(address from, address to, uint256 amount) internal override(ERC20) whenNotPaused notInEmergency {
        super._update(from, to, amount);
    }

    /**
     * @dev Required override for AccessControl
     */
    function supportsInterface(bytes4 interfaceId) public view override(AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

contracts/core/StakingRewards.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title Staking Rewards - Tier-based Staking System
 * @dev staking with tier-based rewards and role management
 */
contract StakingRewards is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ===== ROLES =====
    bytes32 public constant REWARDS_MANAGER_ROLE = keccak256("REWARDS_MANAGER_ROLE");
    bytes32 public constant EMERGENCY_ROLE = keccak256("EMERGENCY_ROLE");

    IERC20 public immutable stakingToken;

    // ===== USER DATA =====
    struct UserStakeData {
        uint128 stakedAmount; // Amount staked
        uint128 pendingRewards; // Pending reward amount
        uint64 lastRewardUpdate; // Last reward calculation time
        uint32 tierLevel; // User tier (0-4)
        uint16 boostMultiplier; // Boost multiplier (basis points)
        bool hasVotingRights; // Voting permission
        bool hasPremiumAccess; // Premium features access
    }

    mapping(address => UserStakeData) private userStakes;

    // ===== GLOBAL STATE =====
    struct GlobalStakingState {
        uint128 totalStaked; // Total amount staked
        uint128 rewardPool; // Available reward pool
        uint64 lastGlobalUpdate; // Last global update time
        uint32 rewardRate; // Rewards per second (scaled)
        uint16 stakingFee; // Staking fee (basis points)
        bool stakingEnabled; // Staking toggle
        bool emergencyWithdraw; // Emergency mode
    }

    GlobalStakingState public globalState;

    // ===== TIER SYSTEM =====
    uint256[5] private tierThresholds = [
        1000 * 10 ** 18, // Bronze: 1K
        5000 * 10 ** 18, // Silver: 5K
        10000 * 10 ** 18, // Gold: 10K
        25000 * 10 ** 18, // Platinum: 25K
        50000 * 10 ** 18 // Diamond: 50K
    ];

    uint16[5] private tierMultipliers = [1000, 1200, 1500, 2000, 3000]; // 100%, 120%, 150%, 200%, 300%

    // ===== EVENTS =====
    event Staked(address indexed user, uint256 amount, uint32 newTier);
    event Withdrawn(address indexed user, uint256 amount, uint32 newTier);
    event RewardsClaimed(address indexed user, uint256 amount, uint256 gasUsed);
    event TierUpgraded(address indexed user, uint32 oldTier, uint32 newTier);

    constructor(address _stakingToken, address _admin) {
        stakingToken = IERC20(_stakingToken);

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(REWARDS_MANAGER_ROLE, _admin);
        _grantRole(EMERGENCY_ROLE, _admin);

        globalState = GlobalStakingState({
            totalStaked: 0,
            rewardPool: 0,
            lastGlobalUpdate: uint64(block.timestamp),
            rewardRate: 0,
            stakingFee: 50, // 0.5%
            stakingEnabled: true,
            emergencyWithdraw: false
        });
    }

    /**
     * @dev staking
     */
    function stake(uint256 amount) external nonReentrant {
        require(globalState.stakingEnabled, "Staking disabled");
        require(amount > 0, "Zero amount");

        UserStakeData storage userData = userStakes[msg.sender];

        // Update rewards before modifying stake
        _updateUserRewards(msg.sender);

        // Calculate fee with unchecked math (amount > 0 validated)
        uint256 fee;
        uint256 netAmount;
        unchecked {
            fee = (amount * globalState.stakingFee) / 10000;
            netAmount = amount - fee;

            // Update user data
            userData.stakedAmount += uint128(netAmount);
            userData.lastRewardUpdate = uint64(block.timestamp);

            // Update global state
            globalState.totalStaked += uint128(netAmount);
        }

        // Update tier and privileges efficiently
        uint32 newTier = _calculateTier(userData.stakedAmount);
        uint32 oldTier = userData.tierLevel;

        if (newTier != oldTier) {
            userData.tierLevel = newTier;
            userData.boostMultiplier = tierMultipliers[newTier];
            userData.hasVotingRights = newTier >= 1; // Silver+
            userData.hasPremiumAccess = newTier >= 2; // Gold+

            emit TierUpgraded(msg.sender, oldTier, newTier);
        }

        // Transfer tokens
        stakingToken.transferFrom(msg.sender, address(this), amount);

        emit Staked(msg.sender, netAmount, newTier);
    }

    /**
     * @dev withdrawal
     */
    function withdraw(uint256 amount) external nonReentrant {
        UserStakeData storage userData = userStakes[msg.sender];
        require(userData.stakedAmount >= amount, "Insufficient stake");

        // Update rewards before withdrawal
        _updateUserRewards(msg.sender);

        // Update balances with unchecked math (amount validated)
        unchecked {
            userData.stakedAmount -= uint128(amount);
            globalState.totalStaked -= uint128(amount);
        }

        // Update tier after withdrawal
        uint32 newTier = _calculateTier(userData.stakedAmount);
        uint32 oldTier = userData.tierLevel;

        if (newTier != oldTier) {
            userData.tierLevel = newTier;
            userData.boostMultiplier = tierMultipliers[newTier];
            userData.hasVotingRights = newTier >= 1;
            userData.hasPremiumAccess = newTier >= 2;

            emit TierUpgraded(msg.sender, oldTier, newTier);
        }

        stakingToken.transfer(msg.sender, amount);
        emit Withdrawn(msg.sender, amount, newTier);
    }

    /**
     * @dev Reward claiming with gas tracking
     */
    function claimRewards() external nonReentrant {
        uint256 gasStart = gasleft();

        _updateUserRewards(msg.sender);

        UserStakeData storage userData = userStakes[msg.sender];
        uint256 rewards = userData.pendingRewards;
        require(rewards > 0, "No rewards");

        userData.pendingRewards = 0;

        // Update global reward pool with unchecked math
        unchecked {
            globalState.rewardPool -= uint128(rewards);
        }

        stakingToken.transfer(msg.sender, rewards);

        uint256 gasUsed = gasStart - gasleft();
        emit RewardsClaimed(msg.sender, rewards, gasUsed);
    }

    /**
     * @dev tier calculation without assembly
     */
    function _calculateTier(uint256 amount) internal view returns (uint32 tier) {
        tier = 0;

        // comparison without assembly
        if (amount >= tierThresholds[0]) tier = 1;
        if (amount >= tierThresholds[1]) tier = 2;
        if (amount >= tierThresholds[2]) tier = 3;
        if (amount >= tierThresholds[3]) tier = 4;
        if (amount >= tierThresholds[4]) tier = 4; // Cap at max tier

        return tier;
    }

    /**
     * @dev reward calculation
     */
    function _updateUserRewards(address user) internal {
        UserStakeData storage userData = userStakes[user];

        if (userData.stakedAmount > 0) {
            uint256 timeDiff = block.timestamp - userData.lastRewardUpdate;

            if (timeDiff > 0) {
                // Calculate base rewards with unchecked math
                unchecked {
                    uint256 baseReward = (userData.stakedAmount * globalState.rewardRate * timeDiff) / 1e18;
                    uint256 boostedReward = (baseReward * userData.boostMultiplier) / 1000;

                    userData.pendingRewards += uint128(boostedReward);
                    userData.lastRewardUpdate = uint64(block.timestamp);
                }
            }
        }
    }

    /**
     * @dev User info getter
     */
    function getUserInfo(
        address user
    )
        external
        view
        returns (
            uint256 stakedAmount,
            uint256 pendingRewards,
            uint32 tierLevel,
            uint16 boostMultiplier,
            bool hasVoting,
            bool hasPremium
        )
    {
        UserStakeData memory userData = userStakes[user];

        // Calculate current pending rewards
        uint256 currentRewards = userData.pendingRewards;
        if (userData.stakedAmount > 0) {
            uint256 timeDiff = block.timestamp - userData.lastRewardUpdate;
            unchecked {
                uint256 baseReward = (userData.stakedAmount * globalState.rewardRate * timeDiff) / 1e18;
                uint256 boostedReward = (baseReward * userData.boostMultiplier) / 1000;
                currentRewards += boostedReward;
            }
        }

        return (
            userData.stakedAmount,
            currentRewards,
            userData.tierLevel,
            userData.boostMultiplier,
            userData.hasVotingRights,
            userData.hasPremiumAccess
        );
    }

    /**
     * @dev Add rewards to the pool
     */
    function addRewards(uint256 amount) external onlyRole(REWARDS_MANAGER_ROLE) {
        unchecked {
            globalState.rewardPool += uint128(amount);
            globalState.rewardRate = uint32(amount / 30 days); // 30-day distribution
        }
        stakingToken.transferFrom(msg.sender, address(this), amount);
    }

    /**
     * @dev Emergency controls
     */
    function toggleEmergencyWithdraw() external onlyRole(EMERGENCY_ROLE) {
        globalState.emergencyWithdraw = !globalState.emergencyWithdraw;
    }

    function toggleStaking() external onlyRole(EMERGENCY_ROLE) {
        globalState.stakingEnabled = !globalState.stakingEnabled;
    }
}

contracts/core/TeamVesting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title Team Vesting - Time-locked Token Vesting
 * @dev vesting with multiple schedule types and role management
 */
contract TeamVesting is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ===== ROLES =====
    bytes32 public constant VESTING_MANAGER_ROLE = keccak256("VESTING_MANAGER_ROLE");
    bytes32 public constant EMERGENCY_ROLE = keccak256("EMERGENCY_ROLE");

    IERC20 public immutable token;

    // ===== VESTING DATA =====
    struct VestingSchedule {
        uint128 totalAmount; // Total tokens to vest
        uint128 released; // Tokens already released
        uint64 startTime; // Vesting start timestamp
        uint32 durationDays; // Vesting duration in days
        uint16 cliffDays; // Cliff period in days
        uint8 vestingType; // 0=linear, 1=stepped, 2=exponential
        bool active; // Schedule active status
    }

    mapping(address => VestingSchedule) private vestingSchedules;

    // ===== METRICS =====
    uint256 public totalVested;
    uint256 public totalReleased;
    uint256 public activeSchedules;

    // ===== EVENTS =====
    event VestingCreated(address indexed beneficiary, uint256 amount, uint32 duration);
    event TokensReleased(address indexed beneficiary, uint256 amount, uint256 remaining);
    event VestingRevoked(address indexed beneficiary, uint256 returned);

    constructor(address _token, address _admin) {
        token = IERC20(_token);
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(VESTING_MANAGER_ROLE, _admin);
        _grantRole(EMERGENCY_ROLE, _admin);
    }

    /**
     * @dev Create vesting schedule
     */
    function createVesting(
        address beneficiary,
        uint256 amount,
        uint32 durationDays,
        uint16 cliffDays,
        uint8 vestingType
    ) external onlyRole(VESTING_MANAGER_ROLE) nonReentrant {
        require(beneficiary != address(0), "Zero address");
        require(amount > 0, "Zero amount");
        require(durationDays > 0, "Zero duration");
        require(cliffDays <= durationDays, "Cliff > duration");
        require(vestingType <= 2, "Invalid type");
        require(!vestingSchedules[beneficiary].active, "Schedule exists");

        vestingSchedules[beneficiary] = VestingSchedule({
            totalAmount: uint128(amount),
            released: 0,
            startTime: uint64(block.timestamp),
            durationDays: durationDays,
            cliffDays: cliffDays,
            vestingType: vestingType,
            active: true
        });

        // Update metrics with unchecked math (safe operations)
        unchecked {
            totalVested += amount;
            activeSchedules += 1;
        }

        emit VestingCreated(beneficiary, amount, durationDays);
    }

    /**
     * @dev release function
     */
    function release() external nonReentrant {
        VestingSchedule storage schedule = vestingSchedules[msg.sender];
        require(schedule.active, "No active schedule");

        uint256 releasable = _calculateReleasable(msg.sender);
        require(releasable > 0, "Nothing to release");

        // Update state with unchecked math (releasable is validated)
        unchecked {
            schedule.released += uint128(releasable);
            totalReleased += releasable;
        }

        token.safeTransfer(msg.sender, releasable);

        uint256 remaining = schedule.totalAmount - schedule.released;
        emit TokensReleased(msg.sender, releasable, remaining);
    }

    /**
     * @dev vested amount calculation
     */
    function _calculateReleasable(address beneficiary) internal view returns (uint256) {
        VestingSchedule memory schedule = vestingSchedules[beneficiary];

        if (!schedule.active) return 0;

        uint256 currentTime = block.timestamp;
        uint256 cliffTime = schedule.startTime + (uint256(schedule.cliffDays) * 1 days);

        if (currentTime < cliffTime) return 0;

        uint256 endTime = schedule.startTime + (uint256(schedule.durationDays) * 1 days);

        uint256 vestedAmount;

        if (currentTime >= endTime) {
            vestedAmount = schedule.totalAmount;
        } else {
            // Unchecked math for time calculations (safe with validated inputs)
            unchecked {
                uint256 timeVested = currentTime - schedule.startTime;
                uint256 totalTime = uint256(schedule.durationDays) * 1 days;

                if (schedule.vestingType == 0) {
                    // Linear
                    vestedAmount = (schedule.totalAmount * timeVested) / totalTime;
                } else if (schedule.vestingType == 1) {
                    // Stepped (monthly)
                    uint256 monthsVested = timeVested / (30 days);
                    uint256 totalMonths = schedule.durationDays / 30;
                    if (totalMonths == 0) totalMonths = 1; // Safety check
                    vestedAmount = (schedule.totalAmount * monthsVested) / totalMonths;
                } else {
                    // Exponential (front-loaded)
                    uint256 progress = (timeVested * 1e18) / totalTime;
                    uint256 curve = (progress * progress) / 1e18; // Quadratic curve
                    vestedAmount = (schedule.totalAmount * curve) / 1e18;
                }
            }
        }

        return vestedAmount - schedule.released;
    }

    /**
     * @dev Calculate releasable amount for beneficiary (view function)
     */
    function releasableAmount(address beneficiary) external view returns (uint256) {
        return _calculateReleasable(beneficiary);
    }

    /**
     * @dev Get vesting info for beneficiary
     */
    function getVestingInfo(
        address beneficiary
    ) external view returns (uint256 totalAmount, uint256 released, uint256 releasable, bool active) {
        VestingSchedule memory schedule = vestingSchedules[beneficiary];

        return (schedule.totalAmount, schedule.released, _calculateReleasable(beneficiary), schedule.active);
    }
}

contracts/creator/incentives/CreatorInce.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "../../interfaces/core/IRovifyToken.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title CreatorIncentives
 * @dev Enhanced creator incentive system with performance-based rewards
 */
contract CreatorIncentives is AccessControl, ReentrancyGuard {
    // ===== ROLES =====
    bytes32 public constant INCENTIVE_MANAGER_ROLE = keccak256("INCENTIVE_MANAGER_ROLE");
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");

    // ===== STATE VARIABLES =====
    IRovifyToken public immutable rovifyToken;

    // ===== ENUMS =====
    enum CreatorTier {
        Bronze,
        Silver,
        Gold,
        Platinum,
        Diamond
    }
    enum RewardType {
        Monthly,
        Performance,
        Milestone,
        Referral,
        Special
    }

    // ===== STRUCTS =====
    struct CreatorProfile {
        CreatorTier tier;
        uint256 stakedAmount; // RVFY staked for tier
        uint256 monthlyRevenue; // Monthly revenue in USD (scaled)
        uint256 followerCount; // Total followers across platforms
        uint256 engagementScore; // Calculated engagement score
        uint256 lastRewardClaim; // Last monthly reward claim
        uint256 totalRewardsClaimed; // Total rewards claimed
        uint256 referralCount; // Number of successful referrals
        bool isVerified; // KYC/verification status
        bool isActive; // Currently active creator
        string[] specialties; // Creator specialties/categories
    }

    struct RewardPool {
        uint256 monthlyPool; // Monthly reward pool
        uint256 performancePool; // Performance bonus pool
        uint256 milestonePool; // Milestone achievement pool
        uint256 referralPool; // Referral reward pool
        uint256 specialPool; // Special campaigns pool
        uint256 currentMonth; // Current month identifier
        uint256 totalDistributed; // Total distributed this month
    }

    struct PerformanceMetrics {
        uint256 contentCreated; // Number of content pieces
        uint256 eventHosted; // Number of events hosted
        uint256 streamHours; // Total streaming hours
        uint256 ticketsSold; // Event tickets sold
        uint256 subscriptionGrowth; // Subscription growth percentage
        uint256 viewerEngagement; // Average viewer engagement
        uint256 communityGrowth; // Community growth metrics
    }

    // ===== STORAGE =====
    mapping(address => CreatorProfile) public creators;
    mapping(address => PerformanceMetrics) public creatorMetrics;
    mapping(CreatorTier => uint256) public tierStakeRequirements;
    mapping(CreatorTier => uint256) public tierRewardMultipliers; // Basis points
    mapping(address => mapping(uint256 => bool)) public monthlyClaimStatus;
    mapping(address => address[]) public referrals; // referrer => referred creators

    RewardPool public rewardPool;

    // ===== CONFIGURATION =====
    struct IncentiveConfig {
        uint256 baseMonthlyReward; // Base monthly reward
        uint256 performanceBonus; // Max performance bonus
        uint256 milestoneReward; // Standard milestone reward
        uint256 referralReward; // Referral reward amount
        uint256 verificationBonus; // Verification bonus multiplier
        uint256 minActiveThreshold; // Minimum activity for rewards
    }

    IncentiveConfig public config;

    // ===== EVENTS =====
    event CreatorRegistered(address indexed creator, CreatorTier tier);
    event CreatorTierUpdated(address indexed creator, CreatorTier oldTier, CreatorTier newTier);
    event MonthlyRewardClaimed(address indexed creator, uint256 amount, uint256 month);
    event PerformanceBonusAwarded(address indexed creator, uint256 amount, string reason);
    event MilestoneAchieved(address indexed creator, string milestone, uint256 reward);
    event ReferralRewardPaid(address indexed referrer, address indexed referred, uint256 amount);
    event CreatorVerified(address indexed creator, address indexed verifier);

    constructor(address _rovifyToken, address _admin) {
        rovifyToken = IRovifyToken(_rovifyToken);

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(INCENTIVE_MANAGER_ROLE, _admin);
        _grantRole(VERIFIER_ROLE, _admin);

        // Initialize tier requirements
        tierStakeRequirements[CreatorTier.Bronze] = 1000 * 10 ** 18; // 1K RVFY
        tierStakeRequirements[CreatorTier.Silver] = 5000 * 10 ** 18; // 5K RVFY
        tierStakeRequirements[CreatorTier.Gold] = 10000 * 10 ** 18; // 10K RVFY
        tierStakeRequirements[CreatorTier.Platinum] = 25000 * 10 ** 18; // 25K RVFY
        tierStakeRequirements[CreatorTier.Diamond] = 50000 * 10 ** 18; // 50K RVFY

        // Initialize tier multipliers (basis points)
        tierRewardMultipliers[CreatorTier.Bronze] = 100; // 1%
        tierRewardMultipliers[CreatorTier.Silver] = 300; // 3%
        tierRewardMultipliers[CreatorTier.Gold] = 600; // 6%
        tierRewardMultipliers[CreatorTier.Platinum] = 1000; // 10%
        tierRewardMultipliers[CreatorTier.Diamond] = 1500; // 15%

        // Initialize reward pools
        rewardPool = RewardPool({
            monthlyPool: 1000000 * 10 ** 18, // 1M RVFY monthly
            performancePool: 500000 * 10 ** 18, // 500K RVFY performance
            milestonePool: 250000 * 10 ** 18, // 250K RVFY milestones
            referralPool: 100000 * 10 ** 18, // 100K RVFY referrals
            specialPool: 150000 * 10 ** 18, // 150K RVFY special
            currentMonth: _getCurrentMonth(),
            totalDistributed: 0
        });

        // Initialize configuration
        config = IncentiveConfig({
            baseMonthlyReward: 1000 * 10 ** 18, // 1K RVFY base
            performanceBonus: 5000 * 10 ** 18, // 5K RVFY max bonus
            milestoneReward: 2000 * 10 ** 18, // 2K RVFY milestone
            referralReward: 500 * 10 ** 18, // 500 RVFY referral
            verificationBonus: 1500, // 15% bonus for verified
            minActiveThreshold: 100 // Minimum activity score
        });
    }

    /**
     * @dev Register as creator
     */
    function registerCreator(CreatorTier tier, string[] calldata specialties, address referrer) external nonReentrant {
        require(!creators[msg.sender].isActive, "Already registered");
        require(specialties.length > 0, "Specialties required");

        uint256 stakeRequired = tierStakeRequirements[tier];

        // Transfer stake
        rovifyToken.transferFrom(msg.sender, address(this), stakeRequired);

        creators[msg.sender] = CreatorProfile({
            tier: tier,
            stakedAmount: stakeRequired,
            monthlyRevenue: 0,
            followerCount: 0,
            engagementScore: 0,
            lastRewardClaim: 0,
            totalRewardsClaimed: 0,
            referralCount: 0,
            isVerified: false,
            isActive: true,
            specialties: specialties
        });

        // Initialize metrics
        creatorMetrics[msg.sender] = PerformanceMetrics({
            contentCreated: 0,
            eventHosted: 0,
            streamHours: 0,
            ticketsSold: 0,
            subscriptionGrowth: 0,
            viewerEngagement: 0,
            communityGrowth: 0
        });

        // Handle referral
        if (referrer != address(0) && creators[referrer].isActive) {
            referrals[referrer].push(msg.sender);
            creators[referrer].referralCount++;

            // Pay referral reward
            uint256 referralReward = config.referralReward;
            rovifyToken.transfer(referrer, referralReward);
            rewardPool.referralPool -= referralReward;

            emit ReferralRewardPaid(referrer, msg.sender, referralReward);
        }

        emit CreatorRegistered(msg.sender, tier);
    }

    /**
     * @dev Claim monthly rewards
     */
    function claimMonthlyReward() external nonReentrant {
        CreatorProfile storage creator = creators[msg.sender];
        require(creator.isActive, "Not active creator");

        uint256 currentMonth = _getCurrentMonth();
        require(!monthlyClaimStatus[msg.sender][currentMonth], "Already claimed this month");
        require(block.timestamp >= creator.lastRewardClaim + 30 days, "Too early to claim");

        // Check minimum activity
        uint256 activityScore = _calculateActivityScore(msg.sender);
        require(activityScore >= config.minActiveThreshold, "Insufficient activity");

        // Calculate reward
        uint256 baseReward = config.baseMonthlyReward;
        uint256 tierMultiplier = tierRewardMultipliers[creator.tier];
        uint256 tierReward = (baseReward * tierMultiplier) / 10000;

        // Verification bonus
        if (creator.isVerified) {
            tierReward = (tierReward * (10000 + config.verificationBonus)) / 10000;
        }

        // Performance bonus
        uint256 performanceBonus = _calculatePerformanceBonus(msg.sender);
        uint256 totalReward = tierReward + performanceBonus;

        // Update state
        creator.lastRewardClaim = block.timestamp;
        creator.totalRewardsClaimed += totalReward;
        monthlyClaimStatus[msg.sender][currentMonth] = true;
        rewardPool.totalDistributed += totalReward;

        // Transfer reward
        rovifyToken.transfer(msg.sender, totalReward);

        emit MonthlyRewardClaimed(msg.sender, totalReward, currentMonth);
    }

    /**
     * @dev Update creator metrics (called by platform contracts)
     */
    function updateCreatorMetrics(
        address creator,
        uint256 contentCreated,
        uint256 eventHosted,
        uint256 streamHours,
        uint256 ticketsSold,
        uint256 subscriptionGrowth
    ) external onlyRole(INCENTIVE_MANAGER_ROLE) {
        require(creators[creator].isActive, "Creator not active");

        PerformanceMetrics storage metrics = creatorMetrics[creator];
        metrics.contentCreated += contentCreated;
        metrics.eventHosted += eventHosted;
        metrics.streamHours += streamHours;
        metrics.ticketsSold += ticketsSold;

        if (subscriptionGrowth > 0) {
            metrics.subscriptionGrowth = subscriptionGrowth;
        }

        // Update engagement score
        creators[creator].engagementScore = _calculateEngagementScore(creator);

        // Check for tier upgrade
        _checkTierUpgrade(creator);
    }

    /**
     * @dev Award milestone achievement
     */
    function awardMilestone(
        address creator,
        string calldata milestone,
        uint256 customReward
    ) external onlyRole(INCENTIVE_MANAGER_ROLE) {
        require(creators[creator].isActive, "Creator not active");

        uint256 reward = customReward > 0 ? customReward : config.milestoneReward;

        creators[creator].totalRewardsClaimed += reward;
        rewardPool.milestonePool -= reward;

        rovifyToken.transfer(creator, reward);

        emit MilestoneAchieved(creator, milestone, reward);
    }

    /**
     * @dev Verify creator (KYC/verification)
     */
    function verifyCreator(address creator) external onlyRole(VERIFIER_ROLE) {
        require(creators[creator].isActive, "Creator not active");

        creators[creator].isVerified = true;
        emit CreatorVerified(creator, msg.sender);
    }

    // ===== INTERNAL FUNCTIONS =====

    /**
     * @dev Calculate activity score
     */
    function _calculateActivityScore(address creator) internal view returns (uint256) {
        PerformanceMetrics memory metrics = creatorMetrics[creator];

        // Simple scoring algorithm (can be enhanced)
        uint256 score = 0;
        score += metrics.contentCreated * 10;
        score += metrics.eventHosted * 25;
        score += metrics.streamHours * 5;
        score += metrics.ticketsSold * 2;
        score += creators[creator].followerCount / 100;

        return score;
    }

    /**
     * @dev Calculate performance bonus
     */
    function _calculatePerformanceBonus(address creator) internal view returns (uint256) {
        uint256 activityScore = _calculateActivityScore(creator);
        uint256 engagementScore = creators[creator].engagementScore;

        // Performance bonus based on activity and engagement
        uint256 bonusPercentage = (activityScore + engagementScore) / 100;
        if (bonusPercentage > 50) bonusPercentage = 50; // Cap at 50%

        return (config.performanceBonus * bonusPercentage) / 100;
    }

    /**
     * @dev Calculate engagement score
     */
    function _calculateEngagementScore(address creator) internal view returns (uint256) {
        PerformanceMetrics memory metrics = creatorMetrics[creator];
        CreatorProfile memory profile = creators[creator];

        // Engagement calculation (simplified)
        uint256 score = 0;
        if (profile.followerCount > 0) {
            score += (metrics.ticketsSold * 100) / profile.followerCount;
            score += metrics.subscriptionGrowth;
            score += metrics.viewerEngagement;
        }

        return score;
    }

    /**
     * @dev Check for tier upgrade
     */
    function _checkTierUpgrade(address creator) internal {
        CreatorProfile storage profile = creators[creator];
        uint256 currentScore = _calculateActivityScore(creator);
        uint256 engagementScore = profile.engagementScore;

        CreatorTier newTier = profile.tier;

        // Tier upgrade logic based on metrics
        if (currentScore >= 10000 && engagementScore >= 5000) {
            newTier = CreatorTier.Diamond;
        } else if (currentScore >= 5000 && engagementScore >= 2500) {
            newTier = CreatorTier.Platinum;
        } else if (currentScore >= 2000 && engagementScore >= 1000) {
            newTier = CreatorTier.Gold;
        } else if (currentScore >= 500 && engagementScore >= 250) {
            newTier = CreatorTier.Silver;
        }

        if (newTier != profile.tier) {
            CreatorTier oldTier = profile.tier;
            profile.tier = newTier;
            emit CreatorTierUpdated(creator, oldTier, newTier);
        }
    }

    /**
     * @dev Get current month identifier
     */
    function _getCurrentMonth() internal view returns (uint256) {
        return (block.timestamp / 30 days);
    }

    // ===== VIEW FUNCTIONS =====

    /**
     * @dev Get creator profile
     */
    function getCreatorProfile(address creator) external view returns (CreatorProfile memory) {
        return creators[creator];
    }

    /**
     * @dev Get creator metrics
     */
    function getCreatorMetrics(address creator) external view returns (PerformanceMetrics memory) {
        return creatorMetrics[creator];
    }

    /**
     * @dev Get tier requirements
     */
    function getTierRequirements(CreatorTier tier) external view returns (uint256 stake, uint256 multiplier) {
        return (tierStakeRequirements[tier], tierRewardMultipliers[tier]);
    }

    /**
     * @dev Get creator referrals
     */
    function getCreatorReferrals(address creator) external view returns (address[] memory) {
        return referrals[creator];
    }

    /**
     * @dev Calculate pending reward
     */
    function calculatePendingReward(address creator) external view returns (uint256) {
        if (!creators[creator].isActive) return 0;

        uint256 currentMonth = _getCurrentMonth();
        if (monthlyClaimStatus[creator][currentMonth]) return 0;

        if (block.timestamp < creators[creator].lastRewardClaim + 30 days) return 0;

        uint256 baseReward = config.baseMonthlyReward;
        uint256 tierMultiplier = tierRewardMultipliers[creators[creator].tier];
        uint256 tierReward = (baseReward * tierMultiplier) / 10000;

        if (creators[creator].isVerified) {
            tierReward = (tierReward * (10000 + config.verificationBonus)) / 10000;
        }

        uint256 performanceBonus = _calculatePerformanceBonus(creator);
        return tierReward + performanceBonus;
    }
}

