contracts/nft/tickets/EventTicketNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "../../interfaces/nft/ITicketNFT.sol";
import "../../interfaces/core/IRovifyToken.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Base64.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title EventTicketNFT
 * @dev NFT tickets for events
 */
contract EventTicketNFT is IEventTicketNFT, ERC721, ERC721Enumerable, ERC721URIStorage, AccessControl, ReentrancyGuard {
    using Strings for uint256;

    // ===== ROLES =====
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");

    // ===== STATE VARIABLES =====
    IRovifyToken public immutable rovifyToken;
    uint256 private _tokenIdCounter;

    // ===== STORAGE =====
    mapping(uint256 => TicketMetadata) private ticketMetadata;
    mapping(uint256 => uint256[]) private eventTickets; // eventId => tokenIds
    mapping(uint256 => bool) private usedTickets;
    mapping(uint256 => string) private customTokenURIs;

    // ===== CONFIGURATION =====
    struct PlatformConfig {
        uint256 transferFee; // Fee for secondary transfers (in RVFY)
        uint256 royaltyRate; // Royalty rate for secondary sales (basis points)
        bool transfersEnabled; // Global transfer toggle
        string baseTokenURI; // Base URI for token metadata
    }

    PlatformConfig public config;

    // ===== EVENTS =====
    event TicketTransferabilityChanged(uint256 indexed tokenId, bool transferable);
    event TransferFeeCollected(uint256 indexed tokenId, uint256 fee);

    constructor(
        address _rovifyToken,
        address _admin,
        string memory _baseTokenURI
    ) ERC721("Rovify Event Ticket", "RET") {
        rovifyToken = IRovifyToken(_rovifyToken);

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(MINTER_ROLE, _admin);
        _grantRole(OPERATOR_ROLE, _admin);

        config = PlatformConfig({
            transferFee: 10 * 10 ** 18, // 10 RVFY
            royaltyRate: 250, // 2.5%
            transfersEnabled: true,
            baseTokenURI: _baseTokenURI
        });

        _tokenIdCounter = 1; // Start from ID 1
    }

    /**
     * @dev Mint a new ticket NFT
     */
    function mintTicket(
        address to,
        uint256 eventId,
        string calldata ticketType,
        bool isTransferable
    ) external onlyRole(MINTER_ROLE) nonReentrant returns (uint256 ticketTokenId) {
        require(to != address(0), "Cannot mint to zero address");
        require(eventId > 0, "Invalid event ID");
        require(bytes(ticketType).length > 0, "Ticket type required");

        ticketTokenId = _tokenIdCounter;
        _tokenIdCounter++;

        // Store ticket metadata
        ticketMetadata[ticketTokenId] = TicketMetadata({
            eventId: eventId,
            originalPurchaser: to,
            purchaseTime: block.timestamp,
            seatNumber: 0, // Can be set later
            ticketType: ticketType,
            isTransferable: isTransferable,
            isUsed: false
        });

        // Add to event tickets
        eventTickets[eventId].push(ticketTokenId);

        // Mint NFT
        _safeMint(to, ticketTokenId);

        // Generate and set token URI
        string memory generatedURI = _generateTokenURI(ticketTokenId);
        _setTokenURI(ticketTokenId, generatedURI);

        emit TicketMinted(ticketTokenId, eventId, to, ticketType);
    }

    /**
     * @dev Use a ticket (mark as used)
     */
    function useTicket(uint256 tokenId) external nonReentrant {
        require(_tokenExists(tokenId), "Token does not exist");
        require(ownerOf(tokenId) == msg.sender || hasRole(OPERATOR_ROLE, msg.sender), "Not authorized to use ticket");
        require(!usedTickets[tokenId], "Ticket already used");

        usedTickets[tokenId] = true;
        ticketMetadata[tokenId].isUsed = true;

        emit TicketUsed(tokenId, ticketMetadata[tokenId].eventId, msg.sender);
    }

    /**
     * @dev Set ticket transferability
     */
    function setTicketTransferability(uint256 tokenId, bool transferable) external onlyRole(OPERATOR_ROLE) {
        require(_tokenExists(tokenId), "Token does not exist");

        ticketMetadata[tokenId].isTransferable = transferable;
        emit TicketTransferabilityChanged(tokenId, transferable);
    }

    /**
     * @dev Set seat number for ticket
     */
    function setSeatNumber(uint256 tokenId, uint256 seatNumber) external onlyRole(OPERATOR_ROLE) {
        require(_tokenExists(tokenId), "Token does not exist");
        ticketMetadata[tokenId].seatNumber = seatNumber;
    }

    /**
     * @dev Override _update to handle restrictions and fees (replaces _beforeTokenTransfer in v5)
     */
    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal virtual override(ERC721, ERC721Enumerable) returns (address) {
        address from = _ownerOf(tokenId);

        // Skip checks for minting and burning
        if (from != address(0) && to != address(0)) {
            require(config.transfersEnabled, "Transfers disabled");
            require(ticketMetadata[tokenId].isTransferable, "Ticket not transferable");
            require(!usedTickets[tokenId], "Cannot transfer used ticket");

            // Collect transfer fee (if applicable)
            if (config.transferFee > 0) {
                rovifyToken.transferFrom(from, address(this), config.transferFee);
                emit TransferFeeCollected(tokenId, config.transferFee);
            }
        }

        return super._update(to, tokenId, auth);
    }

    /**
     * @dev Check if token exists (replaces deprecated _exists in v5)
     */
    function _tokenExists(uint256 tokenId) internal view returns (bool) {
        return _ownerOf(tokenId) != address(0);
    }

    /**
     * @dev Generate dynamic token URI
     */
    function _generateTokenURI(uint256 tokenId) internal view returns (string memory) {
        TicketMetadata memory metadata = ticketMetadata[tokenId];

        // Create JSON metadata
        string memory json = string(
            abi.encodePacked(
                '{"name": "Event Ticket #',
                tokenId.toString(),
                '", "description": "Rovify Event Ticket for Event #',
                metadata.eventId.toString(),
                '", "image": "',
                config.baseTokenURI,
                "/images/",
                tokenId.toString(),
                ".png",
                '", "attributes": [',
                '{"trait_type": "Event ID", "value": "',
                metadata.eventId.toString(),
                '"},',
                '{"trait_type": "Ticket Type", "value": "',
                metadata.ticketType,
                '"},',
                '{"trait_type": "Purchase Time", "value": "',
                metadata.purchaseTime.toString(),
                '"},',
                '{"trait_type": "Transferable", "value": "',
                metadata.isTransferable ? "true" : "false",
                '"},',
                '{"trait_type": "Used", "value": "',
                metadata.isUsed ? "true" : "false",
                '"}'
            )
        );

        if (metadata.seatNumber > 0) {
            json = string(
                abi.encodePacked(
                    json,
                    ', {"trait_type": "Seat Number", "value": "',
                    metadata.seatNumber.toString(),
                    '"}'
                )
            );
        }

        json = string(abi.encodePacked(json, "]}"));

        return string(abi.encodePacked("data:application/json;base64,", Base64.encode(bytes(json))));
    }

    /**
     * @dev Update platform configuration
     */
    function updateConfig(PlatformConfig calldata newConfig) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newConfig.royaltyRate <= 1000, "Royalty rate too high"); // Max 10%
        config = newConfig;
    }

    // ===== VIEW FUNCTIONS =====

    /**
     * @dev Get ticket metadata
     */
    function getTicketMetadata(uint256 tokenId) external view returns (TicketMetadata memory) {
        require(_tokenExists(tokenId), "Token does not exist");
        return ticketMetadata[tokenId];
    }

    /**
     * @dev Get all tickets for an event
     */
    function getEventTickets(uint256 eventId) external view returns (uint256[] memory) {
        return eventTickets[eventId];
    }

    /**
     * @dev Check if ticket is used
     */
    function isTicketUsed(uint256 tokenId) external view returns (bool) {
        require(_tokenExists(tokenId), "Token does not exist");
        return usedTickets[tokenId];
    }

    /**
     * @dev Get tickets owned by address
     */
    function getOwnerTickets(address owner) external view returns (uint256[] memory tokens) {
        uint256 balance = balanceOf(owner);
        tokens = new uint256[](balance);

        for (uint256 i = 0; i < balance; i++) {
            tokens[i] = tokenOfOwnerByIndex(owner, i);
        }
    }

    /**
     * @dev Get event tickets for owner
     */
    function getOwnerEventTickets(address owner, uint256 eventId) external view returns (uint256[] memory tokens) {
        uint256[] memory allEventTickets = eventTickets[eventId];
        uint256[] memory tempTokens = new uint256[](allEventTickets.length);
        uint256 count = 0;

        for (uint256 i = 0; i < allEventTickets.length; i++) {
            if (ownerOf(allEventTickets[i]) == owner) {
                tempTokens[count] = allEventTickets[i];
                count++;
            }
        }

        // Copy to correctly sized array
        tokens = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            tokens[i] = tempTokens[i];
        }
    }

    /**
     * @dev Get current token ID counter
     */
    function getCurrentTokenId() external view returns (uint256) {
        return _tokenIdCounter;
    }

    /**
     * @dev Check if token exists (public version)
     */
    function exists(uint256 tokenId) external view returns (bool) {
        return _tokenExists(tokenId);
    }

    // ===== REQUIRED OVERRIDES =====

    function tokenURI(uint256 tokenId) public view override(ERC721, ERC721URIStorage) returns (string memory) {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(
        bytes4 interfaceId
    ) public view override(ERC721, ERC721Enumerable, ERC721URIStorage, AccessControl, IERC165) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    function _increaseBalance(address account, uint128 value) internal override(ERC721, ERC721Enumerable) {
        super._increaseBalance(account, value);
    }
}

contracts/platform/events/EventFactory.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "../../interfaces/platform/IEventManagement.sol";
import "../../interfaces/core/IRovifyToken.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title EventFactory
 * @dev Factory contract for creating and managing events
 */
contract EventFactory is IEventFactory, AccessControl, ReentrancyGuard {
    // ===== ROLES =====
    bytes32 public constant EVENT_MANAGER_ROLE = keccak256("EVENT_MANAGER_ROLE");
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");

    // ===== STATE VARIABLES =====
    IRovifyToken public immutable rovifyToken;
    uint256 private _eventIdCounter;

    // ===== STORAGE =====
    mapping(uint256 => EventParams) private events;
    mapping(uint256 => address) public eventCreators;
    mapping(address => uint256[]) private creatorEvents;
    mapping(uint256 => bool) public eventExists;
    mapping(uint256 => bool) public verifiedEvents;

    // ===== CONFIGURATION =====
    struct PlatformConfig {
        uint256 creationFee; // Fee to create event (in RVFY)
        uint256 platformFeeRate; // Basis points (e.g., 250 = 2.5%)
        uint256 minEventDuration; // Minimum event duration
        uint256 maxEventDuration; // Maximum event duration
        bool requireVerification; // Require events to be verified
    }

    PlatformConfig public config;

    // ===== EVENTS =====
    event EventUpdated(uint256 indexed eventId, address indexed creator);
    event EventVerified(uint256 indexed eventId, address indexed verifier);
    event PlatformConfigUpdated(uint256 creationFee, uint256 platformFeeRate);

    // ===== MODIFIERS =====
    modifier eventExistsModifier(uint256 eventId) {
        require(eventExists[eventId], "Event does not exist");
        _;
    }

    modifier onlyEventCreator(uint256 eventId) {
        require(eventCreators[eventId] == msg.sender, "Not event creator");
        _;
    }

    modifier validEventParams(EventParams calldata params) {
        require(bytes(params.name).length > 0, "Name required");
        require(params.startTime > block.timestamp, "Start time must be future");
        require(params.endTime > params.startTime, "End time must be after start");
        require(params.maxAttendees > 0, "Max attendees must be positive");

        uint256 duration = params.endTime - params.startTime;
        require(duration >= config.minEventDuration, "Event too short");
        require(duration <= config.maxEventDuration, "Event too long");
        _;
    }

    constructor(address _rovifyToken, address _admin) {
        rovifyToken = IRovifyToken(_rovifyToken);

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(EVENT_MANAGER_ROLE, _admin);
        _grantRole(VERIFIER_ROLE, _admin);

        // Initialize platform configuration
        config = PlatformConfig({
            creationFee: 1000 * 10 ** 18, // 1000 RVFY
            platformFeeRate: 250, // 2.5%
            minEventDuration: 1 hours, // 1 hour minimum
            maxEventDuration: 30 days, // 30 days maximum
            requireVerification: false // Initially no verification required
        });

        _eventIdCounter = 1; // Start from ID 1
    }

    /**
     * @dev Create a new event
     */
    function createEvent(
        EventParams calldata params
    ) external validEventParams(params) nonReentrant returns (uint256 eventId) {
        // Charge creation fee
        if (config.creationFee > 0) {
            rovifyToken.transferFrom(msg.sender, address(this), config.creationFee);
        }

        eventId = _eventIdCounter;
        _eventIdCounter++;

        // Store event data
        events[eventId] = params;
        eventCreators[eventId] = msg.sender;
        creatorEvents[msg.sender].push(eventId);
        eventExists[eventId] = true;

        emit EventCreated(eventId, msg.sender, params.name, params.startTime, params.ticketPrice);
    }

    /**
     * @dev Update an existing event
     */
    function updateEvent(
        uint256 eventId,
        EventParams calldata params
    ) external eventExistsModifier(eventId) onlyEventCreator(eventId) validEventParams(params) nonReentrant {
        // Prevent updates too close to event start
        require(block.timestamp < events[eventId].startTime - 1 hours, "Too close to event start");

        events[eventId] = params;
        emit EventUpdated(eventId, msg.sender);
    }

    /**
     * @dev Cancel an event
     */
    function cancelEvent(uint256 eventId) external eventExistsModifier(eventId) onlyEventCreator(eventId) nonReentrant {
        require(block.timestamp < events[eventId].startTime, "Event already started");

        // Mark as cancelled by setting endTime to 0
        events[eventId].endTime = 0;

        emit EventUpdated(eventId, msg.sender);
    }

    /**
     * @dev Verify an event (admin/verifier only)
     */
    function verifyEvent(uint256 eventId) external eventExistsModifier(eventId) onlyRole(VERIFIER_ROLE) {
        verifiedEvents[eventId] = true;
        emit EventVerified(eventId, msg.sender);
    }

    /**
     * @dev Update platform configuration
     */
    function updatePlatformConfig(PlatformConfig calldata newConfig) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newConfig.platformFeeRate <= 1000, "Fee rate too high"); // Max 10%
        require(newConfig.minEventDuration <= newConfig.maxEventDuration, "Invalid duration range");

        config = newConfig;
        emit PlatformConfigUpdated(newConfig.creationFee, newConfig.platformFeeRate);
    }

    // ===== VIEW FUNCTIONS =====

    /**
     * @dev Get event details
     */
    function getEvent(uint256 eventId) external view eventExistsModifier(eventId) returns (EventParams memory) {
        return events[eventId];
    }

    /**
     * @dev Get all events created by a creator
     */
    function getCreatorEvents(address creator) external view returns (uint256[] memory) {
        return creatorEvents[creator];
    }

    /**
     * @dev Get current event ID counter
     */
    function getCurrentEventId() external view returns (uint256) {
        return _eventIdCounter;
    }

    /**
     * @dev Check if event is verified
     */
    function isEventVerified(uint256 eventId) external view eventExistsModifier(eventId) returns (bool) {
        return verifiedEvents[eventId];
    }

    /**
     * @dev Get platform configuration
     */
    function getPlatformConfig() external view returns (PlatformConfig memory) {
        return config;
    }

    /**
     * @dev Get multiple events in batch
     */
    function getEventsBatch(uint256[] calldata eventIds) external view returns (EventParams[] memory results) {
        results = new EventParams[](eventIds.length);

        for (uint256 i = 0; i < eventIds.length; i++) {
            if (eventExists[eventIds[i]]) {
                results[i] = events[eventIds[i]];
            }
        }
    }

    /**
     * @dev Get events by time range
     */
    function getEventsByTimeRange(
        uint256 startTime,
        uint256 endTime
    ) external view returns (uint256[] memory eventIds) {
        uint256 currentId = _eventIdCounter;
        uint256[] memory tempIds = new uint256[](currentId);
        uint256 count = 0;

        for (uint256 i = 1; i < currentId; i++) {
            if (eventExists[i]) {
                EventParams memory eventData = events[i];
                if (eventData.startTime >= startTime && eventData.startTime <= endTime) {
                    tempIds[count] = i;
                    count++;
                }
            }
        }

        // Copy to correctly sized array
        eventIds = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            eventIds[i] = tempIds[i];
        }
    }

    /**
     * @dev Search events by tags
     */
    function getEventsByTag(string calldata tag) external view returns (uint256[] memory eventIds) {
        uint256 currentId = _eventIdCounter;
        uint256[] memory tempIds = new uint256[](currentId);
        uint256 count = 0;

        for (uint256 i = 1; i < currentId; i++) {
            if (eventExists[i]) {
                EventParams memory eventData = events[i];
                for (uint256 j = 0; j < eventData.tags.length; j++) {
                    if (keccak256(bytes(eventData.tags[j])) == keccak256(bytes(tag))) {
                        tempIds[count] = i;
                        count++;
                        break;
                    }
                }
            }
        }

        // Copy to correctly sized array
        eventIds = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            eventIds[i] = tempIds[i];
        }
    }
}

contracts/platform/events/EventManager.s.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "../../interfaces/platform/IEventManagement.sol";
import "../../interfaces/nft/ITicketNFT.sol";

/**
 * @title EventManager
 * @dev event lifecycle mgmnt
 * @notice Handles event status transitions, check-ins, and real-time attendee tracking
 */
contract EventManager is AccessControl, ReentrancyGuard {
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant EMERGENCY_ROLE = keccak256("EMERGENCY_ROLE");

    enum EventStatus {
        Created,
        Active,
        Paused,
        Cancelled,
        Completed
    }

    struct EventState {
        uint128 attendeeCount; // Current checked-in attendees
        uint64 statusChangeTime; // Last status change timestamp
        uint32 maxAttendees; // Maximum allowed attendees
        uint8 status; // EventStatus enum (0-4)
        bool checkInEnabled; // Check-in functionality toggle
        // Slot 1: 16 + 8 + 4 + 1 + 1 = 30 bytes (2 bytes unused)
    }

    struct CheckInData {
        uint128 checkInTime; // When attendee checked in
        uint128 ticketId; // Associated ticket NFT ID
        // Slot 1: 16 + 16 = 32 bytes (perfect slot utilization)
    }

    // Mappings
    mapping(uint256 => EventState) public eventStates;
    mapping(uint256 => mapping(address => CheckInData)) public attendeeCheckIns;
    mapping(uint256 => address[]) public eventAttendees;

    // Rate limiting for anti-bot protection
    mapping(address => uint256) public lastActionTime;
    uint256 public constant MIN_ACTION_INTERVAL = 2 seconds;

    // Events
    event EventStatusChanged(uint256 indexed eventId, EventStatus oldStatus, EventStatus newStatus, address operator);
    event AttendeeCheckedIn(
        uint256 indexed eventId,
        address indexed attendee,
        uint256 indexed ticketId,
        uint256 timestamp
    );
    event BatchCheckInCompleted(uint256 indexed eventId, uint256 attendeeCount, uint256 gasUsed);
    event MaxAttendeesUpdated(uint256 indexed eventId, uint32 oldMax, uint32 newMax);

    error EventNotFound();
    error InvalidStatusTransition();
    error CheckInDisabled();
    error MaxAttendeesReached();
    error AttendeeAlreadyCheckedIn();
    error InvalidTicketForEvent();
    error UnauthorizedTicketHolder();
    error RateLimitExceeded();
    error InvalidBatchSize();

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(OPERATOR_ROLE, admin);
        _grantRole(EMERGENCY_ROLE, admin);
    }

    /**
     * @dev Initialize event state when created by EventFactory
     * @param eventId Unique event identifier
     * @param maxAttendees Maximum number of attendees allowed
     */
    function initializeEvent(uint256 eventId, uint32 maxAttendees) external onlyRole(OPERATOR_ROLE) {
        require(eventStates[eventId].statusChangeTime == 0, "Event already initialized");

        eventStates[eventId] = EventState({
            attendeeCount: 0,
            statusChangeTime: uint64(block.timestamp),
            maxAttendees: maxAttendees,
            status: uint8(EventStatus.Created),
            checkInEnabled: false
        });

        emit EventStatusChanged(eventId, EventStatus.Created, EventStatus.Created, msg.sender);
    }

    /**
     * @dev Start event and enable check-ins
     * @param eventId Event to start
     */
    function startEvent(uint256 eventId) external onlyRole(OPERATOR_ROLE) {
        EventState storage state = eventStates[eventId];
        require(state.statusChangeTime != 0, "Event not found");
        require(state.status == uint8(EventStatus.Created), "Invalid status transition");

        uint256 gasStart = gasleft();

        unchecked {
            state.status = uint8(EventStatus.Active);
            state.statusChangeTime = uint64(block.timestamp);
            state.checkInEnabled = true;
        }

        uint256 gasUsed = gasStart - gasleft();
        emit EventStatusChanged(eventId, EventStatus.Created, EventStatus.Active, msg.sender);

        // Gas optimization tracking for continuous improvement
        if (gasUsed > 50000) {
            // Log for optimization review if gas usage is high
            emit BatchCheckInCompleted(eventId, 0, gasUsed);
        }
    }

    /**
     * @dev Pause event (emergency scenarios)
     * @param eventId Event to pause
     */
    function pauseEvent(uint256 eventId) external onlyRole(EMERGENCY_ROLE) {
        EventState storage state = eventStates[eventId];
        require(state.status == uint8(EventStatus.Active), "Can only pause active events");

        unchecked {
            state.status = uint8(EventStatus.Paused);
            state.statusChangeTime = uint64(block.timestamp);
            state.checkInEnabled = false;
        }

        emit EventStatusChanged(eventId, EventStatus.Active, EventStatus.Paused, msg.sender);
    }

    /**
     * @dev Resume paused event
     * @param eventId Event to resume
     */
    function resumeEvent(uint256 eventId) external onlyRole(OPERATOR_ROLE) {
        EventState storage state = eventStates[eventId];
        require(state.status == uint8(EventStatus.Paused), "Can only resume paused events");

        unchecked {
            state.status = uint8(EventStatus.Active);
            state.statusChangeTime = uint64(block.timestamp);
            state.checkInEnabled = true;
        }

        emit EventStatusChanged(eventId, EventStatus.Paused, EventStatus.Active, msg.sender);
    }

    /**
     * @dev Complete event and finalize attendance
     * @param eventId Event to complete
     */
    function completeEvent(uint256 eventId) external onlyRole(OPERATOR_ROLE) {
        EventState storage state = eventStates[eventId];
        require(
            state.status == uint8(EventStatus.Active) || state.status == uint8(EventStatus.Paused),
            "Invalid status for completion"
        );

        unchecked {
            state.status = uint8(EventStatus.Completed);
            state.statusChangeTime = uint64(block.timestamp);
            state.checkInEnabled = false;
        }

        emit EventStatusChanged(eventId, EventStatus(state.status), EventStatus.Completed, msg.sender);
    }

    /**
     * @dev Cancel event (emergency or creator decision)
     * @param eventId Event to cancel
     */
    function cancelEvent(uint256 eventId) external onlyRole(EMERGENCY_ROLE) {
        EventState storage state = eventStates[eventId];
        require(state.status != uint8(EventStatus.Completed), "Cannot cancel completed event");
        require(state.status != uint8(EventStatus.Cancelled), "Event already cancelled");

        EventStatus oldStatus = EventStatus(state.status);

        unchecked {
            state.status = uint8(EventStatus.Cancelled);
            state.statusChangeTime = uint64(block.timestamp);
            state.checkInEnabled = false;
        }

        emit EventStatusChanged(eventId, oldStatus, EventStatus.Cancelled, msg.sender);
    }

    /**
     * @dev Check in single attendee with QR code verification
     * @param eventId Event ID
     * @param attendee Attendee address
     * @param ticketId NFT ticket ID for verification
     */
    function checkInAttendee(
        uint256 eventId,
        address attendee,
        uint256 ticketId
    ) external onlyRole(OPERATOR_ROLE) nonReentrant {
        // Rate limiting protection
        require(block.timestamp >= lastActionTime[msg.sender] + MIN_ACTION_INTERVAL, "Rate limit exceeded");
        lastActionTime[msg.sender] = block.timestamp;

        EventState storage state = eventStates[eventId];
        require(state.checkInEnabled, "Check-in disabled");
        require(state.attendeeCount < state.maxAttendees, "Max attendees reached");
        require(attendeeCheckIns[eventId][attendee].checkInTime == 0, "Already checked in");

        // Verify ticket ownership and validity
        // TODO: Integrate with TicketNFT contract for verification
        // ITicketNFT ticketContract = ITicketNFT(ticketNFTAddress);
        // require(ticketContract.ownerOf(ticketId) == attendee, "Invalid ticket holder");
        // require(ticketContract.getEventId(ticketId) == eventId, "Ticket not for this event");

        uint256 gasStart = gasleft();

        // Update state
        unchecked {
            state.attendeeCount += 1;
            attendeeCheckIns[eventId][attendee] = CheckInData({
                checkInTime: uint128(block.timestamp),
                ticketId: uint128(ticketId)
            });
        }

        eventAttendees[eventId].push(attendee);

        uint256 gasUsed = gasStart - gasleft();
        emit AttendeeCheckedIn(eventId, attendee, ticketId, block.timestamp);

        // Track gas usage for optimization
        if (gasUsed > 35000) {
            emit BatchCheckInCompleted(eventId, 1, gasUsed);
        }
    }

    /**
     * @dev Batch check-in for efficient mass processing
     * @param eventId Event ID
     * @param attendees Array of attendee addresses
     * @param ticketIds Array of corresponding ticket IDs
     */
    function batchCheckIn(
        uint256 eventId,
        address[] calldata attendees,
        uint256[] calldata ticketIds
    ) external onlyRole(OPERATOR_ROLE) nonReentrant {
        require(attendees.length == ticketIds.length, "Array length mismatch");
        require(attendees.length <= 50, "Batch too large"); // Gas limit protection
        require(attendees.length > 0, "Empty batch");

        EventState storage state = eventStates[eventId];
        require(state.checkInEnabled, "Check-in disabled");

        uint256 gasStart = gasleft();
        uint256 successfulCheckIns = 0;

        for (uint256 i = 0; i < attendees.length; ) {
            address attendee = attendees[i];
            uint256 ticketId = ticketIds[i];

            // Skip if already checked in or invalid
            if (attendeeCheckIns[eventId][attendee].checkInTime == 0 && state.attendeeCount < state.maxAttendees) {
                unchecked {
                    state.attendeeCount += 1;
                    attendeeCheckIns[eventId][attendee] = CheckInData({
                        checkInTime: uint128(block.timestamp),
                        ticketId: uint128(ticketId)
                    });
                    successfulCheckIns += 1;
                }

                eventAttendees[eventId].push(attendee);
                emit AttendeeCheckedIn(eventId, attendee, ticketId, block.timestamp);
            }

            unchecked {
                ++i;
            }
        }

        uint256 gasUsed = gasStart - gasleft();
        emit BatchCheckInCompleted(eventId, successfulCheckIns, gasUsed);
    }

    /**
     * @dev Update maximum attendees (before event starts)
     * @param eventId Event ID
     * @param newMaxAttendees New maximum attendee count
     */
    function updateMaxAttendees(uint256 eventId, uint32 newMaxAttendees) external onlyRole(OPERATOR_ROLE) {
        EventState storage state = eventStates[eventId];
        require(state.status == uint8(EventStatus.Created), "Can only update before event starts");
        require(newMaxAttendees >= state.attendeeCount, "Cannot set below current attendance");

        uint32 oldMax = state.maxAttendees;
        state.maxAttendees = newMaxAttendees;

        emit MaxAttendeesUpdated(eventId, oldMax, newMaxAttendees);
    }

    // VIEW FUNCTIONS

    /**
     * @dev Get complete event state
     * @param eventId Event ID
     * @return Event state struct
     */
    function getEventState(uint256 eventId) external view returns (EventState memory) {
        return eventStates[eventId];
    }

    /**
     * @dev Get attendee check-in data
     * @param eventId Event ID
     * @param attendee Attendee address
     * @return Check-in data struct
     */
    function getAttendeeCheckIn(uint256 eventId, address attendee) external view returns (CheckInData memory) {
        return attendeeCheckIns[eventId][attendee];
    }

    /**
     * @dev Get all checked-in attendees for an event
     * @param eventId Event ID
     * @return Array of attendee addresses
     */
    function getEventAttendees(uint256 eventId) external view returns (address[] memory) {
        return eventAttendees[eventId];
    }

    /**
     * @dev Check if attendee is checked in
     * @param eventId Event ID
     * @param attendee Attendee address
     * @return True if checked in
     */
    function isAttendeeCheckedIn(uint256 eventId, address attendee) external view returns (bool) {
        return attendeeCheckIns[eventId][attendee].checkInTime > 0;
    }

    /**
     * @dev Get event attendance statistics
     * @param eventId Event ID
     * @return attendeeCount Current attendees
     * @return maxAttendees Maximum allowed
     * @return attendanceRate Percentage (basis points)
     */
    function getAttendanceStats(
        uint256 eventId
    ) external view returns (uint256 attendeeCount, uint256 maxAttendees, uint256 attendanceRate) {
        EventState memory state = eventStates[eventId];
        attendeeCount = state.attendeeCount;
        maxAttendees = state.maxAttendees;

        if (maxAttendees > 0) {
            unchecked {
                attendanceRate = (attendeeCount * 10000) / maxAttendees;
            }
        }
    }
}

contracts/platform/events/EventPayouts.s.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "../../interfaces/platform/IEventManagement.sol";
import "../../core/BurnMechanism.sol";

/**
 * @title EventPayouts
 * @dev creator revenue distribution system
 * @notice Handles automated payouts, multi-creator splits, and platform fee distribution
 */
contract EventPayouts is AccessControl, ReentrancyGuard {
    bytes32 public constant PAYOUT_MANAGER_ROLE = keccak256("PAYOUT_MANAGER_ROLE");
    bytes32 public constant TREASURY_ROLE = keccak256("TREASURY_ROLE");
    bytes32 public constant EMERGENCY_ROLE = keccak256("EMERGENCY_ROLE");

    enum PayoutStatus {
        Pending,
        Processed,
        Emergency,
        Disputed
    }

    // storage: 32 bytes exactly (1 slot)
    struct PayoutConfiguration {
        uint128 totalRevenue; // Total event revenue
        uint64 payoutTime; // When payout was processed
        uint32 creatorCount; // Number of creators splitting revenue
        uint16 platformFeeBps; // Platform fee (basis points)
        uint8 status; // PayoutStatus enum
        bool emergencyWithdrawn; // Emergency withdrawal flag
        // Total: 16 + 8 + 4 + 2 + 1 + 1 = 32 bytes (perfect slot)
    }

    // storage: 32 bytes exactly (1 slot)
    struct CreatorSplit {
        uint128 amount; // Creator's share amount
        uint64 claimTime; // When creator claimed payout
        uint32 percentage; // Creator's percentage (basis points)
        bool claimed; // Whether creator has claimed
        // Total: 16 + 8 + 4 + 1 = 29 bytes (3 bytes unused)
    }

    struct SecondaryRoyalty {
        uint128 totalVolume; // Total secondary sales volume
        uint128 totalRoyalties; // Total royalties earned
        uint64 lastSaleTime; // Last secondary sale timestamp
        uint32 salesCount; // Number of secondary sales
        // Total: 16 + 16 + 8 + 4 = 44 bytes (2 slots)
    }

    // State variables
    BurnMechanism public immutable burnMechanism;
    address public treasury;

    // Platform configuration
    uint16 public platformFeeBps = 250; // 2.5% platform fee
    uint16 public secondaryRoyaltyBps = 750; // 7.5% creator royalty on secondary sales
    uint16 public secondaryPlatformBps = 250; // 2.5% platform fee on secondary sales
    uint16 public maxCreators = 10; // Maximum creators per event

    // Emergency controls
    bool public emergencyPaused = false;
    uint256 public emergencyDelay = 7 days; // 7-day delay for emergency withdrawals

    // Mappings
    mapping(uint256 => PayoutConfiguration) public payoutConfigs;
    mapping(uint256 => mapping(address => CreatorSplit)) public creatorSplits;
    mapping(uint256 => address[]) public eventCreators;
    mapping(uint256 => SecondaryRoyalty) public secondaryRoyalties;
    mapping(address => uint256) public pendingWithdrawals;

    // Revenue tracking
    mapping(uint256 => uint256) public eventRevenues;
    mapping(uint256 => uint256) public platformFees;
    uint256 public totalBurnedFromFees;

    // Events
    event PayoutConfigured(uint256 indexed eventId, address[] creators, uint256[] percentages, uint256 totalRevenue);

    event PayoutProcessed(
        uint256 indexed eventId,
        uint256 totalRevenue,
        uint256 platformFee,
        uint256 burnAmount,
        uint256 gasUsed
    );

    event CreatorPayout(uint256 indexed eventId, address indexed creator, uint256 amount, uint256 timestamp);

    event BatchPayoutCompleted(uint256[] eventIds, uint256 totalProcessed, uint256 gasUsed);

    event SecondaryRoyaltyPaid(uint256 indexed eventId, address indexed creator, uint256 amount, uint256 salePrice);

    event EmergencyWithdrawal(uint256 indexed eventId, address indexed creator, uint256 amount);

    // Errors
    error InvalidCreatorSplit();
    error PayoutAlreadyProcessed();
    error PayoutNotReady();
    error CreatorNotFound();
    error AlreadyClaimed();
    error InsufficientRevenue();
    error EmergencyPaused();
    error InvalidConfiguration();
    error UnauthorizedAccess();
    error EmergencyDelayNotMet();

    modifier notEmergencyPaused() {
        require(!emergencyPaused, "Emergency paused");
        _;
    }

    constructor(address _burnMechanism, address _treasury, address admin) {
        burnMechanism = BurnMechanism(_burnMechanism);
        treasury = _treasury;

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAYOUT_MANAGER_ROLE, admin);
        _grantRole(TREASURY_ROLE, admin);
        _grantRole(EMERGENCY_ROLE, admin);
    }

    /**
     * @dev Set creator revenue splits for an event
     * @param eventId Event identifier
     * @param creators Array of creator addresses
     * @param percentages Array of percentage splits (basis points)
     */
    function setCreatorSplits(
        uint256 eventId,
        address[] calldata creators,
        uint256[] calldata percentages
    ) external onlyRole(PAYOUT_MANAGER_ROLE) {
        require(creators.length == percentages.length, "Array mismatch");
        require(creators.length <= maxCreators, "Too many creators");
        require(creators.length > 0, "No creators specified");

        // Validate percentages sum to 10000 (100%)
        uint256 totalPercentage = 0;
        for (uint256 i = 0; i < percentages.length; ) {
            require(percentages[i] > 0, "Invalid percentage");
            unchecked {
                totalPercentage += percentages[i];
                ++i;
            }
        }
        require(totalPercentage == 10000, "Percentages must sum to 100%");

        // Clear existing splits
        address[] storage existingCreators = eventCreators[eventId];
        for (uint256 i = 0; i < existingCreators.length; ) {
            delete creatorSplits[eventId][existingCreators[i]];
            unchecked {
                ++i;
            }
        }
        delete eventCreators[eventId];

        // Set new splits
        for (uint256 i = 0; i < creators.length; ) {
            address creator = creators[i];
            require(creator != address(0), "Invalid creator address");

            creatorSplits[eventId][creator] = CreatorSplit({
                amount: 0, // Will be calculated during payout
                claimTime: 0,
                percentage: uint32(percentages[i]),
                claimed: false
            });

            eventCreators[eventId].push(creator);
            unchecked {
                ++i;
            }
        }

        emit PayoutConfigured(eventId, creators, percentages, 0);
    }

    /**
     * @dev Calculate and execute payouts for a completed event
     * @param eventId Event identifier
     * @param totalRevenue Total revenue from ticket sales
     */
    function executePayouts(
        uint256 eventId,
        uint256 totalRevenue
    ) external onlyRole(PAYOUT_MANAGER_ROLE) nonReentrant notEmergencyPaused {
        require(totalRevenue > 0, "No revenue to distribute");

        PayoutConfiguration storage config = payoutConfigs[eventId];
        require(config.status == uint8(PayoutStatus.Pending), "Payout already processed");

        uint256 gasStart = gasleft();

        // Calculate platform fee
        uint256 platformFee;
        unchecked {
            platformFee = (totalRevenue * platformFeeBps) / 10000;
        }

        // Calculate burn amount (25% of platform fees per BurnMechanism)
        uint256 burnAmount;
        unchecked {
            burnAmount = (platformFee * 2500) / 10000; // 25% of platform fees
        }

        // Remaining revenue after platform fee
        uint256 creatorRevenue;
        unchecked {
            creatorRevenue = totalRevenue - platformFee;
        }

        // Calculate creator payouts
        address[] memory creators = eventCreators[eventId];
        require(creators.length > 0, "No creators configured");

        for (uint256 i = 0; i < creators.length; ) {
            address creator = creators[i];
            CreatorSplit storage split = creatorSplits[eventId][creator];

            unchecked {
                split.amount = uint128((creatorRevenue * split.percentage) / 10000);
                ++i;
            }
        }

        // Update payout configuration
        unchecked {
            config.totalRevenue = uint128(totalRevenue);
            config.payoutTime = uint64(block.timestamp);
            config.creatorCount = uint32(creators.length);
            config.platformFeeBps = platformFeeBps;
            config.status = uint8(PayoutStatus.Processed);
        }

        // Store revenue tracking
        eventRevenues[eventId] = creatorRevenue;
        platformFees[eventId] = platformFee;

        // Send burn amount to BurnMechanism
        if (burnAmount > 0) {
            (bool burnSuccess, ) = address(burnMechanism).call{ value: burnAmount }("");
            if (burnSuccess) {
                unchecked {
                    totalBurnedFromFees += burnAmount;
                }
            }
        }

        // Send remaining platform fee to treasury
        uint256 treasuryAmount;
        unchecked {
            treasuryAmount = platformFee - burnAmount;
        }

        if (treasuryAmount > 0) {
            (bool treasurySuccess, ) = treasury.call{ value: treasuryAmount }("");
            require(treasurySuccess, "Treasury transfer failed");
        }

        uint256 gasUsed = gasStart - gasleft();
        emit PayoutProcessed(eventId, totalRevenue, platformFee, burnAmount, gasUsed);
    }

    /**
     * @dev Claim creator payout for a specific event
     * @param eventId Event identifier
     */
    function claimCreatorPayout(uint256 eventId) external nonReentrant notEmergencyPaused {
        CreatorSplit storage split = creatorSplits[eventId][msg.sender];
        require(split.percentage > 0, "Not a creator for this event");
        require(!split.claimed, "Already claimed");
        require(split.amount > 0, "No payout available");

        PayoutConfiguration memory config = payoutConfigs[eventId];
        require(config.status == uint8(PayoutStatus.Processed), "Payout not processed");

        uint256 amount = split.amount;

        // Mark as claimed
        split.claimed = true;
        unchecked {
            split.claimTime = uint64(block.timestamp);
        }

        // Transfer payout
        (bool success, ) = msg.sender.call{ value: amount }("");
        require(success, "Payout transfer failed");

        emit CreatorPayout(eventId, msg.sender, amount, block.timestamp);
    }

    /**
     * @dev Batch claim payouts for multiple events
     * @param eventIds Array of event IDs to claim from
     */
    function batchClaimPayouts(uint256[] calldata eventIds) external nonReentrant notEmergencyPaused {
        require(eventIds.length <= 20, "Batch too large");
        require(eventIds.length > 0, "Empty batch");

        uint256 totalAmount = 0;

        for (uint256 i = 0; i < eventIds.length; ) {
            uint256 eventId = eventIds[i];
            CreatorSplit storage split = creatorSplits[eventId][msg.sender];

            if (split.percentage > 0 && !split.claimed && split.amount > 0) {
                PayoutConfiguration memory config = payoutConfigs[eventId];
                if (config.status == uint8(PayoutStatus.Processed)) {
                    unchecked {
                        totalAmount += split.amount;
                        split.claimTime = uint64(block.timestamp);
                    }
                    split.claimed = true;

                    emit CreatorPayout(eventId, msg.sender, split.amount, block.timestamp);
                }
            }

            unchecked {
                ++i;
            }
        }

        require(totalAmount > 0, "No payouts available");

        // Single transfer for all payouts
        (bool success, ) = msg.sender.call{ value: totalAmount }("");
        require(success, "Batch payout transfer failed");
    }

    /**
     * @dev Process secondary sale royalty payment
     * @param eventId Event identifier
     * @param creator Creator address
     * @param salePrice Secondary sale price
     */
    function processSecondaryRoyalty(
        uint256 eventId,
        address creator,
        uint256 salePrice
    ) external payable onlyRole(PAYOUT_MANAGER_ROLE) nonReentrant {
        require(salePrice > 0, "Invalid sale price");
        require(msg.value > 0, "No royalty payment");

        // Calculate royalty amounts
        uint256 creatorRoyalty;
        uint256 platformRoyalty;

        unchecked {
            creatorRoyalty = (salePrice * secondaryRoyaltyBps) / 10000;
            platformRoyalty = (salePrice * secondaryPlatformBps) / 10000;
        }

        require(msg.value >= creatorRoyalty + platformRoyalty, "Insufficient royalty payment");

        // Update secondary royalty tracking
        SecondaryRoyalty storage royalty = secondaryRoyalties[eventId];
        unchecked {
            royalty.totalVolume += uint128(salePrice);
            royalty.totalRoyalties += uint128(creatorRoyalty);
            royalty.lastSaleTime = uint64(block.timestamp);
            royalty.salesCount += 1;
        }

        // Add to creator's pending withdrawals
        unchecked {
            pendingWithdrawals[creator] += creatorRoyalty;
        }

        // Send platform royalty to treasury
        if (platformRoyalty > 0) {
            (bool success, ) = treasury.call{ value: platformRoyalty }("");
            require(success, "Platform royalty transfer failed");
        }

        // Refund excess payment
        uint256 excess = msg.value - (creatorRoyalty + platformRoyalty);
        if (excess > 0) {
            (bool refundSuccess, ) = msg.sender.call{ value: excess }("");
            require(refundSuccess, "Excess refund failed");
        }

        emit SecondaryRoyaltyPaid(eventId, creator, creatorRoyalty, salePrice);
    }

    /**
     * @dev Withdraw accumulated secondary royalties
     */
    function withdrawSecondaryRoyalties() external nonReentrant notEmergencyPaused {
        uint256 amount = pendingWithdrawals[msg.sender];
        require(amount > 0, "No royalties to withdraw");

        pendingWithdrawals[msg.sender] = 0;

        (bool success, ) = msg.sender.call{ value: amount }("");
        require(success, "Royalty withdrawal failed");
    }

    /**
     * @dev Emergency withdrawal for creators (with delay)
     * @param eventId Event identifier
     */
    function emergencyWithdrawRevenue(uint256 eventId) external onlyRole(EMERGENCY_ROLE) nonReentrant {
        PayoutConfiguration storage config = payoutConfigs[eventId];
        require(!config.emergencyWithdrawn, "Already emergency withdrawn");
        require(block.timestamp >= config.payoutTime + emergencyDelay, "Emergency delay not met");

        config.emergencyWithdrawn = true;
        config.status = uint8(PayoutStatus.Emergency);

        uint256 remainingRevenue = eventRevenues[eventId];
        if (remainingRevenue > 0) {
            eventRevenues[eventId] = 0;

            (bool success, ) = treasury.call{ value: remainingRevenue }("");
            require(success, "Emergency withdrawal failed");

            emit EmergencyWithdrawal(eventId, treasury, remainingRevenue);
        }
    }

    /**
     * @dev Toggle emergency pause
     * @param paused New pause status
     */
    function setEmergencyPause(bool paused) external onlyRole(EMERGENCY_ROLE) {
        emergencyPaused = paused;
    }

    /**
     * @dev Update platform fee percentage
     * @param newFeeBps New fee in basis points
     */
    function updatePlatformFee(uint16 newFeeBps) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newFeeBps <= 1000, "Fee too high"); // Max 10%
        platformFeeBps = newFeeBps;
    }

    /**
     * @dev Update secondary royalty percentages
     * @param creatorBps Creator royalty basis points
     * @param platformBps Platform royalty basis points
     */
    function updateSecondaryRoyalties(uint16 creatorBps, uint16 platformBps) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(creatorBps + platformBps <= 2000, "Total royalty too high"); // Max 20%
        secondaryRoyaltyBps = creatorBps;
        secondaryPlatformBps = platformBps;
    }

    // VIEW FUNCTIONS

    /**
     * @dev Calculate payout amounts for an event
     * @param eventId Event identifier
     * @param totalRevenue Total revenue amount
     * @return platformFee Platform fee amount
     * @return burnAmount Amount to be burned
     * @return creatorRevenue Total creator revenue
     */
    function calculatePayouts(
        uint256 eventId,
        uint256 totalRevenue
    ) external view returns (uint256 platformFee, uint256 burnAmount, uint256 creatorRevenue) {
        unchecked {
            platformFee = (totalRevenue * platformFeeBps) / 10000;
            burnAmount = (platformFee * 2500) / 10000; // 25% of platform fees
            creatorRevenue = totalRevenue - platformFee;
        }
    }

    /**
     * @dev Get creator split information
     * @param eventId Event identifier
     * @param creator Creator address
     * @return Creator split data
     */
    function getCreatorSplit(uint256 eventId, address creator) external view returns (CreatorSplit memory) {
        return creatorSplits[eventId][creator];
    }

    /**
     * @dev Get all creators for an event
     * @param eventId Event identifier
     * @return Array of creator addresses
     */
    function getEventCreators(uint256 eventId) external view returns (address[] memory) {
        return eventCreators[eventId];
    }

    /**
     * @dev Get secondary royalty data for an event
     * @param eventId Event identifier
     * @return Secondary royalty struct
     */
    function getSecondaryRoyalties(uint256 eventId) external view returns (SecondaryRoyalty memory) {
        return secondaryRoyalties[eventId];
    }

    /**
     * @dev Get pending secondary royalty amount for a creator
     * @param creator Creator address
     * @return Pending withdrawal amount
     */
    function getPendingRoyalties(address creator) external view returns (uint256) {
        return pendingWithdrawals[creator];
    }

    /**
     * @dev Check if creator has unclaimed payouts
     * @param creator Creator address
     * @param eventIds Array of event IDs to check
     * @return totalUnclaimed Total unclaimed amount
     * @return claimableEvents Number of events with claimable payouts
     */
    function getUnclaimedPayouts(
        address creator,
        uint256[] calldata eventIds
    ) external view returns (uint256 totalUnclaimed, uint256 claimableEvents) {
        for (uint256 i = 0; i < eventIds.length; ) {
            uint256 eventId = eventIds[i];
            CreatorSplit memory split = creatorSplits[eventId][creator];
            PayoutConfiguration memory config = payoutConfigs[eventId];

            if (!split.claimed && split.amount > 0 && config.status == uint8(PayoutStatus.Processed)) {
                unchecked {
                    totalUnclaimed += split.amount;
                    claimableEvents += 1;
                }
            }

            unchecked {
                ++i;
            }
        }
    }

    // Allow contract to receive ETH for payouts
    receive() external payable {}
}

contracts/platform/events/TicketMarketpl.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import { IEventTicketNFT as ITicketNFT } from "../../interfaces/nft/ITicketNFT.sol";
import "../../core/RovifyToken.sol";
import "./EventPayouts.sol";

/**
 * @title TicketMarketplace
 * @dev ticket marketplace with anti-scalping protection
 * @notice Handles secondary sales, auctions, royalties, and creator revenue distribution
 */
contract TicketMarketplace is AccessControl, ReentrancyGuard {
    bytes32 public constant MARKETPLACE_MANAGER_ROLE = keccak256("MARKETPLACE_MANAGER_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant ANTI_SCALPING_ROLE = keccak256("ANTI_SCALPING_ROLE");

    enum ListingType {
        FixedPrice,
        Auction,
        Bundle
    }
    enum ListingStatus {
        Active,
        Sold,
        Cancelled,
        Expired
    }

    // storage: 32 bytes exactly (1 slot)
    struct Listing {
        uint128 price; // Listing price in wei
        uint64 expiresAt; // Listing expiration timestamp
        uint32 eventId; // Event identifier
        uint16 quantity; // Number of tickets (for bundles)
        uint8 listingType; // ListingType enum
        uint8 status; // ListingStatus enum
        bool allowRVFY; // Accept RVFY payments
        // Total: 16 + 8 + 4 + 2 + 1 + 1 + 1 = 33 bytes (needs 2 slots)
    }

    // storage: 32 bytes exactly (1 slot)
    struct AuctionData {
        uint128 highestBid; // Current highest bid
        uint64 auctionEnd; // Auction end timestamp
        uint32 bidCount; // Number of bids placed
        address highestBidder; // Current highest bidder (20 bytes)
        // Total: 16 + 8 + 4 + 20 = 48 bytes (needs 2 slots)
    }

    struct PriceHistory {
        uint128 price; // Sale price
        uint64 saleTime; // Sale timestamp
        uint32 eventId; // Event identifier
        address buyer; // Buyer address (20 bytes)
        address seller; // Seller address (20 bytes)
        // Total: 16 + 8 + 4 + 20 + 20 = 68 bytes (needs 3 slots)
    }

    // State variables
    RovifyToken public immutable rovifyToken;
    ITicketNFT public immutable ticketNFT;
    EventPayouts public immutable eventPayouts;

    // Platform configuration
    uint16 public platformFeeBps = 250; // 2.5% platform fee
    uint16 public creatorRoyaltyBps = 750; // 7.5% creator royalty
    uint16 public rvfyDiscountBps = 1000; // 10% RVFY discount
    uint16 public maxPriceMultiplier = 300; // 3x original price maximum
    uint256 public minListingDuration = 1 hours;
    uint256 public maxListingDuration = 30 days;

    // Anti-scalping configuration
    uint256 public scalpingThreshold = 150; // 50% above original price
    uint256 public scalpingCooldown = 24 hours; // 24-hour cooldown after purchase
    mapping(address => uint256) public lastPurchaseTime;
    mapping(uint256 => uint256) public originalTicketPrices;

    // Mappings
    mapping(uint256 => Listing) public listings; // tokenId => Listing
    mapping(uint256 => AuctionData) public auctions; // tokenId => AuctionData
    mapping(uint256 => uint256[]) public eventListings; // eventId => tokenIds[]
    mapping(address => uint256[]) public userListings; // user => tokenIds[]
    mapping(uint256 => PriceHistory[]) public priceHistory; // eventId => PriceHistory[]

    // Revenue tracking
    mapping(uint256 => uint256) public eventVolumes; // eventId => total volume
    mapping(address => uint256) public sellerEarnings; // seller => total earnings
    uint256 public totalMarketplaceVolume;
    uint256 public totalRoyaltiesPaid;

    // Bid tracking for auctions
    mapping(uint256 => mapping(address => uint256)) public bidAmounts;
    mapping(address => uint256) public pendingWithdrawals;

    // Events
    event TicketListed(
        uint256 indexed tokenId,
        uint256 indexed eventId,
        address indexed seller,
        uint256 price,
        ListingType listingType,
        uint256 expiresAt
    );

    event TicketSold(
        uint256 indexed tokenId,
        uint256 indexed eventId,
        address indexed seller,
        address buyer,
        uint256 price,
        bool usedRVFY
    );

    event AuctionBid(uint256 indexed tokenId, address indexed bidder, uint256 amount, uint256 auctionEnd);

    event ListingCancelled(uint256 indexed tokenId, address indexed seller);
    event RoyaltyPaid(uint256 indexed eventId, address indexed creator, uint256 amount);
    event AntiScalpingTriggered(uint256 indexed tokenId, address indexed seller, uint256 price);

    // Errors
    error NotTicketOwner();
    error ListingNotActive();
    error InsufficientPayment();
    error AuctionNotEnded();
    error BidTooLow();
    error ScalpingDetected();
    error PriceAboveMaximum();
    error InvalidListingDuration();
    error SelfPurchase();
    error TransferFailed();

    modifier onlyTicketOwner(uint256 tokenId) {
        require(ticketNFT.ownerOf(tokenId) == msg.sender, "Not ticket owner");
        _;
    }

    modifier antiScalping(uint256 tokenId, uint256 price) {
        uint256 originalPrice = originalTicketPrices[tokenId];
        if (originalPrice > 0) {
            uint256 maxAllowedPrice = (originalPrice * (10000 + scalpingThreshold)) / 10000;
            require(price <= maxAllowedPrice, "Price above anti-scalping limit");

            // Enforce cooldown period
            require(block.timestamp >= lastPurchaseTime[msg.sender] + scalpingCooldown, "Scalping cooldown active");
        }
        _;
    }

    constructor(address _rovifyToken, address _ticketNFT, address _eventPayouts, address admin) {
        rovifyToken = RovifyToken(_rovifyToken);
        ticketNFT = ITicketNFT(_ticketNFT);
        eventPayouts = EventPayouts(payable(_eventPayouts));

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(MARKETPLACE_MANAGER_ROLE, admin);
        _grantRole(OPERATOR_ROLE, admin);
        _grantRole(ANTI_SCALPING_ROLE, admin);
    }

    /**
     * @dev List ticket for fixed price sale
     * @param tokenId Ticket NFT token ID
     * @param price Listing price in wei
     * @param duration Listing duration in seconds
     * @param allowRVFY Whether to accept RVFY payments
     */
    function listTicket(
        uint256 tokenId,
        uint256 price,
        uint256 duration,
        bool allowRVFY
    ) external onlyTicketOwner(tokenId) antiScalping(tokenId, price) nonReentrant {
        require(price > 0, "Price must be greater than 0");
        require(duration >= minListingDuration && duration <= maxListingDuration, "Invalid duration");

        // Check price against maximum multiplier
        uint256 originalPrice = originalTicketPrices[tokenId];
        if (originalPrice > 0) {
            uint256 maxPrice = (originalPrice * maxPriceMultiplier * 100) / 10000;
            require(price <= maxPrice, "Price above maximum");
        }

        uint32 eventId = _getEventId(tokenId);
        uint64 expiresAt = uint64(block.timestamp + duration);

        // Transfer ticket to marketplace for escrow
        ticketNFT.transferFrom(msg.sender, address(this), tokenId);

        // Create listing
        listings[tokenId] = Listing({
            price: uint128(price),
            expiresAt: expiresAt,
            eventId: eventId,
            quantity: 1,
            listingType: uint8(ListingType.FixedPrice),
            status: uint8(ListingStatus.Active),
            allowRVFY: allowRVFY
        });

        // Track listing
        eventListings[eventId].push(tokenId);
        userListings[msg.sender].push(tokenId);

        emit TicketListed(tokenId, eventId, msg.sender, price, ListingType.FixedPrice, expiresAt);
    }

    /**
     * @dev Create auction for ticket
     * @param tokenId Ticket NFT token ID
     * @param startingPrice Minimum bid price
     * @param duration Auction duration in seconds
     */
    function createAuction(
        uint256 tokenId,
        uint256 startingPrice,
        uint256 duration
    ) external onlyTicketOwner(tokenId) antiScalping(tokenId, startingPrice) nonReentrant {
        require(startingPrice > 0, "Starting price must be greater than 0");
        require(duration >= minListingDuration && duration <= maxListingDuration, "Invalid duration");

        uint32 eventId = _getEventId(tokenId);
        uint64 auctionEnd = uint64(block.timestamp + duration);

        // Transfer ticket to marketplace for escrow
        ticketNFT.transferFrom(msg.sender, address(this), tokenId);

        // Create listing
        listings[tokenId] = Listing({
            price: uint128(startingPrice),
            expiresAt: auctionEnd,
            eventId: eventId,
            quantity: 1,
            listingType: uint8(ListingType.Auction),
            status: uint8(ListingStatus.Active),
            allowRVFY: false // Auctions only accept ETH
        });

        // Create auction data
        auctions[tokenId] = AuctionData({
            highestBid: 0,
            auctionEnd: auctionEnd,
            bidCount: 0,
            highestBidder: address(0)
        });

        eventListings[eventId].push(tokenId);
        userListings[msg.sender].push(tokenId);

        emit TicketListed(tokenId, eventId, msg.sender, startingPrice, ListingType.Auction, auctionEnd);
    }

    /**
     * @dev Purchase ticket at fixed price with ETH
     * @param tokenId Ticket NFT token ID
     */
    function buyTicket(uint256 tokenId) external payable nonReentrant {
        Listing storage listing = listings[tokenId];
        require(listing.status == uint8(ListingStatus.Active), "Listing not active");
        require(block.timestamp <= listing.expiresAt, "Listing expired");
        require(listing.listingType == uint8(ListingType.FixedPrice), "Not a fixed price listing");
        require(msg.value >= listing.price, "Insufficient payment");

        address seller = ticketNFT.ownerOf(tokenId);
        require(msg.sender != seller, "Cannot buy own ticket");

        uint256 gasStart = gasleft();
        _processSale(tokenId, listing.price, false);

        // Refund excess payment
        if (msg.value > listing.price) {
            unchecked {
                uint256 refund = msg.value - listing.price;
                (bool success, ) = msg.sender.call{ value: refund }("");
                require(success, "Refund failed");
            }
        }

        uint256 gasUsed = gasStart - gasleft();

        // Emit events
        emit TicketSold(tokenId, listing.eventId, seller, msg.sender, listing.price, false);

        // Track gas for optimization
        if (gasUsed > 120000) {
            // Log for gas optimization review
        }
    }

    /**
     * @dev Purchase ticket with RVFY tokens (with discount)
     * @param tokenId Ticket NFT token ID
     */
    function buyTicketWithRVFY(uint256 tokenId) external nonReentrant {
        Listing storage listing = listings[tokenId];
        require(listing.status == uint8(ListingStatus.Active), "Listing not active");
        require(block.timestamp <= listing.expiresAt, "Listing expired");
        require(listing.allowRVFY, "RVFY payments not accepted");
        require(listing.listingType == uint8(ListingType.FixedPrice), "Not a fixed price listing");

        address seller = ticketNFT.ownerOf(tokenId);
        require(msg.sender != seller, "Cannot buy own ticket");

        // Calculate discounted price
        uint256 discountedPrice;
        unchecked {
            discountedPrice = listing.price - (listing.price * rvfyDiscountBps) / 10000;
        }

        // Transfer RVFY tokens
        require(rovifyToken.transferFrom(msg.sender, address(this), discountedPrice), "RVFY transfer failed");

        _processSale(tokenId, listing.price, true);

        emit TicketSold(tokenId, listing.eventId, seller, msg.sender, discountedPrice, true);
    }

    /**
     * @dev Place bid on auction
     * @param tokenId Ticket NFT token ID
     */
    function placeBid(uint256 tokenId) external payable nonReentrant {
        Listing storage listing = listings[tokenId];
        AuctionData storage auction = auctions[tokenId];

        require(listing.status == uint8(ListingStatus.Active), "Auction not active");
        require(block.timestamp <= auction.auctionEnd, "Auction ended");
        require(listing.listingType == uint8(ListingType.Auction), "Not an auction");
        require(msg.value > auction.highestBid, "Bid too low");
        require(msg.value >= listing.price, "Bid below starting price");

        address previousBidder = auction.highestBidder;
        uint256 previousBid = auction.highestBid;

        // Update auction state
        auction.highestBid = uint128(msg.value);
        auction.highestBidder = msg.sender;
        unchecked {
            auction.bidCount += 1;
        }

        // Store bid amount for potential withdrawal
        bidAmounts[tokenId][msg.sender] = msg.value;

        // Refund previous highest bidder
        if (previousBidder != address(0) && previousBid > 0) {
            unchecked {
                pendingWithdrawals[previousBidder] += previousBid;
            }
            bidAmounts[tokenId][previousBidder] = 0;
        }

        // Extend auction if bid placed in last 15 minutes
        if (auction.auctionEnd - block.timestamp < 15 minutes) {
            unchecked {
                auction.auctionEnd = uint64(block.timestamp + 15 minutes);
            }
        }

        emit AuctionBid(tokenId, msg.sender, msg.value, auction.auctionEnd);
    }

    /**
     * @dev Finalize auction after end time
     * @param tokenId Ticket NFT token ID
     */
    function finalizeAuction(uint256 tokenId) external nonReentrant {
        Listing storage listing = listings[tokenId];
        AuctionData storage auction = auctions[tokenId];

        require(listing.listingType == uint8(ListingType.Auction), "Not an auction");
        require(block.timestamp > auction.auctionEnd, "Auction not ended");
        require(listing.status == uint8(ListingStatus.Active), "Already finalized");

        if (auction.highestBidder != address(0)) {
            // Process sale to highest bidder
            _processSale(tokenId, auction.highestBid, false);

            emit TicketSold(
                tokenId,
                listing.eventId,
                ticketNFT.ownerOf(tokenId),
                auction.highestBidder,
                auction.highestBid,
                false
            );
        } else {
            // No bids - return ticket to seller
            listing.status = uint8(ListingStatus.Expired);
            ticketNFT.transferFrom(address(this), ticketNFT.ownerOf(tokenId), tokenId);
        }
    }

    /**
     * @dev Cancel active listing
     * @param tokenId Ticket NFT token ID
     */
    function cancelListing(uint256 tokenId) external nonReentrant {
        Listing storage listing = listings[tokenId];
        require(listing.status == uint8(ListingStatus.Active), "Listing not active");

        // Only seller or marketplace manager can cancel
        address seller = ticketNFT.ownerOf(tokenId);
        require(msg.sender == seller || hasRole(MARKETPLACE_MANAGER_ROLE, msg.sender), "Unauthorized");

        // Cannot cancel auction with bids
        if (listing.listingType == uint8(ListingType.Auction)) {
            AuctionData memory auction = auctions[tokenId];
            require(auction.highestBidder == address(0), "Cannot cancel auction with bids");
        }

        listing.status = uint8(ListingStatus.Cancelled);

        // Return ticket to seller
        ticketNFT.transferFrom(address(this), seller, tokenId);

        emit ListingCancelled(tokenId, seller);
    }

    /**
     * @dev Withdraw pending bid refunds
     */
    function withdrawBidRefunds() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        require(amount > 0, "No pending withdrawals");

        pendingWithdrawals[msg.sender] = 0;

        (bool success, ) = msg.sender.call{ value: amount }("");
        require(success, "Withdrawal failed");
    }

    /**
     * @dev Batch list multiple tickets
     * @param tokenIds Array of token IDs
     * @param prices Array of prices
     * @param duration Listing duration
     * @param allowRVFY Whether to accept RVFY
     */
    function batchListTickets(
        uint256[] calldata tokenIds,
        uint256[] calldata prices,
        uint256 duration,
        bool allowRVFY
    ) external nonReentrant {
        require(tokenIds.length == prices.length, "Array mismatch");
        require(tokenIds.length <= 10, "Batch too large");
        require(tokenIds.length > 0, "Empty batch");

        for (uint256 i = 0; i < tokenIds.length; ) {
            require(ticketNFT.ownerOf(tokenIds[i]) == msg.sender, "Not owner");
            // Additional validation would go here
            unchecked {
                ++i;
            }
        }

        // Process batch listing
        for (uint256 i = 0; i < tokenIds.length; ) {
            // Implementation similar to individual listTicket
            unchecked {
                ++i;
            }
        }
    }

    // INTERNAL FUNCTIONS

    function _processSale(uint256 tokenId, uint256 price, bool usedRVFY) internal {
        Listing storage listing = listings[tokenId];
        address seller = ticketNFT.ownerOf(tokenId);

        // Mark as sold
        listing.status = uint8(ListingStatus.Sold);

        // Calculate fees and royalties
        uint256 platformFee;
        uint256 creatorRoyalty;
        uint256 sellerAmount;

        unchecked {
            platformFee = (price * platformFeeBps) / 10000;
            creatorRoyalty = (price * creatorRoyaltyBps) / 10000;
            sellerAmount = price - platformFee - creatorRoyalty;
        }

        // Update tracking
        unchecked {
            eventVolumes[listing.eventId] += price;
            sellerEarnings[seller] += sellerAmount;
            totalMarketplaceVolume += price;
            totalRoyaltiesPaid += creatorRoyalty;
            lastPurchaseTime[msg.sender] = block.timestamp;
        }

        // Record price history
        priceHistory[listing.eventId].push(
            PriceHistory({
                price: uint128(price),
                saleTime: uint64(block.timestamp),
                eventId: listing.eventId,
                buyer: msg.sender,
                seller: seller
            })
        );

        // Transfer ticket to buyer
        ticketNFT.transferFrom(address(this), msg.sender, tokenId);

        // Distribute payments
        if (!usedRVFY) {
            // ETH payments
            if (sellerAmount > 0) {
                (bool sellerSuccess, ) = seller.call{ value: sellerAmount }("");
                require(sellerSuccess, "Seller payment failed");
            }

            // Process creator royalty through EventPayouts
            if (creatorRoyalty > 0) {
                (bool royaltySuccess, ) = address(eventPayouts).call{ value: creatorRoyalty }(
                    abi.encodeWithSignature(
                        "processSecondaryRoyalty(uint256,address,uint256)",
                        listing.eventId,
                        seller, // Simplified - should get actual creator
                        price
                    )
                );
                require(royaltySuccess, "Royalty payment failed");
            }
        } else {
            // RVFY payments - transfer directly to seller
            require(rovifyToken.transfer(seller, sellerAmount), "RVFY seller payment failed");
        }
    }

    function _getEventId(uint256 tokenId) internal view returns (uint32) {
        // Implementation would call TicketNFT to get event ID
        return 1; // Placeholder
    }

    // VIEW FUNCTIONS

    /**
     * @dev Get active listings for an event
     * @param eventId Event identifier
     * @return tokenIds Array of listed token IDs
     */
    function getEventListings(uint256 eventId) external view returns (uint256[] memory tokenIds) {
        uint256[] memory allListings = eventListings[eventId];
        uint256 activeCount = 0;

        // Count active listings
        for (uint256 i = 0; i < allListings.length; ) {
            if (listings[allListings[i]].status == uint8(ListingStatus.Active)) {
                unchecked {
                    activeCount++;
                }
            }
            unchecked {
                ++i;
            }
        }

        // Build active array
        tokenIds = new uint256[](activeCount);
        uint256 index = 0;

        for (uint256 i = 0; i < allListings.length; ) {
            if (listings[allListings[i]].status == uint8(ListingStatus.Active)) {
                tokenIds[index] = allListings[i];
                unchecked {
                    index++;
                }
            }
            unchecked {
                ++i;
            }
        }
    }

    /**
     * @dev Get price history for an event
     * @param eventId Event identifier
     * @return Price history array
     */
    function getPriceHistory(uint256 eventId) external view returns (PriceHistory[] memory) {
        return priceHistory[eventId];
    }

    /**
     * @dev Get marketplace statistics
     * @return totalVolume Total marketplace volume
     * @return totalRoyalties Total royalties paid
     * @return activeListings Number of active listings
     */
    function getMarketplaceStats()
        external
        view
        returns (uint256 totalVolume, uint256 totalRoyalties, uint256 activeListings)
    {
        totalVolume = totalMarketplaceVolume;
        totalRoyalties = totalRoyaltiesPaid;
        // activeListings calculation would require iteration
    }

    // Allow contract to receive ETH for marketplace operations
    receive() external payable {}
}

contracts/platform/events/TicketSales.so.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IEventTicketNFT as ITicketNFT } from "../../interfaces/nft/ITicketNFT.sol";
import "../../core/RovifyToken.sol";

/**
 * @title TicketSales
 * @dev ticket sales engine with RVFY integration
 * @notice Handles flexible sale configurations, payments, discounts, and anti-bot protection
 */
contract TicketSales is AccessControl, ReentrancyGuard {
    bytes32 public constant SALES_MANAGER_ROLE = keccak256("SALES_MANAGER_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant TREASURY_ROLE = keccak256("TREASURY_ROLE");

    // storage: 2 slots instead of 6+ standard
    struct SaleConfiguration {
        uint128 price; // Ticket price in wei
        uint128 maxSupply; // Maximum tickets available
        uint64 saleStart; // Sale start timestamp
        uint64 saleEnd; // Sale end timestamp
        uint32 maxPerWallet; // Maximum tickets per wallet
        uint16 rvfyDiscountBps; // RVFY payment discount (basis points)
        bool whitelistOnly; // Whitelist-only sale
        bool active; // Sale active status
        // Slot 1: 16 + 16 = 32 bytes
        // Slot 2: 8 + 8 + 4 + 2 + 1 + 1 = 24 bytes (8 bytes unused)
    }

    struct SaleMetrics {
        uint128 totalSold; // Total tickets sold
        uint128 totalRevenue; // Total ETH revenue
        uint64 lastPurchaseTime; // Last purchase timestamp
        uint32 uniquePurchasers; // Number of unique buyers
        // Slot 1: 16 + 16 + 8 + 4 = 44 bytes (too big for 1 slot)
        // Actual: 2 slots with 20 bytes unused in slot 2
    }

    struct PurchaseData {
        uint128 amountPaid; // Amount paid in wei
        uint64 purchaseTime; // Purchase timestamp
        uint32 quantity; // Number of tickets purchased
        bool usedRVFY; // Whether RVFY was used for discount
        // Slot 1: 16 + 8 + 4 + 1 = 29 bytes (3 bytes unused)
    }

    // State variables
    RovifyToken public immutable rovifyToken;
    ITicketNFT public immutable ticketNFT;
    address public treasury;

    // Platform configuration
    uint16 public platformFeeBps = 250; // 2.5% platform fee
    uint16 public maxRvfyDiscountBps = 1500; // 15% max RVFY discount
    uint256 public minPurchaseInterval = 3 seconds; // Anti-bot protection

    // Mappings
    mapping(uint256 => SaleConfiguration) public saleConfigs;
    mapping(uint256 => SaleMetrics) public saleMetrics;
    mapping(uint256 => mapping(address => PurchaseData)) public purchaseHistory;
    mapping(uint256 => mapping(address => bool)) public whitelists;
    mapping(address => uint256) public lastPurchaseTime;

    // Revenue tracking
    mapping(uint256 => uint256) public eventRevenues;
    uint256 public totalPlatformFees;

    // Events
    event SaleConfigured(
        uint256 indexed eventId,
        uint128 price,
        uint128 maxSupply,
        uint64 saleStart,
        uint64 saleEnd,
        bool whitelistOnly
    );

    event TicketsPurchased(
        uint256 indexed eventId,
        address indexed buyer,
        uint256 quantity,
        uint256 totalPaid,
        bool usedRVFY,
        uint256[] tokenIds
    );

    event BatchPurchaseCompleted(
        address indexed buyer,
        uint256[] eventIds,
        uint256[] quantities,
        uint256 totalPaid,
        uint256 gasUsed
    );

    event WhitelistUpdated(uint256 indexed eventId, address[] users, bool added);
    event RefundProcessed(uint256 indexed eventId, address indexed buyer, uint256 amount);
    event SaleStatusChanged(uint256 indexed eventId, bool active);

    // Errors
    error SaleNotActive();
    error SaleNotStarted();
    error SaleEnded();
    error InsufficientSupply();
    error ExceedsWalletLimit();
    error InsufficientPayment();
    error NotWhitelisted();
    error PurchaseTooSoon();
    error InvalidConfiguration();
    error UnauthorizedAccess();
    error RefundFailed();
    error InvalidBatchSize();

    constructor(address _rovifyToken, address _ticketNFT, address _treasury, address admin) {
        rovifyToken = RovifyToken(_rovifyToken);
        ticketNFT = ITicketNFT(_ticketNFT);
        treasury = _treasury;

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(SALES_MANAGER_ROLE, admin);
        _grantRole(OPERATOR_ROLE, admin);
        _grantRole(TREASURY_ROLE, admin);
    }

    /**
     * @dev Configure sale parameters for an event
     * @param eventId Event identifier
     * @param config Sale configuration struct
     */
    function configureSale(uint256 eventId, SaleConfiguration calldata config) external onlyRole(SALES_MANAGER_ROLE) {
        require(config.price > 0, "Price must be greater than 0");
        require(config.maxSupply > 0, "Max supply must be greater than 0");
        require(config.saleStart < config.saleEnd, "Invalid sale period");
        require(config.saleStart >= block.timestamp, "Sale start in past");
        require(config.maxPerWallet > 0, "Max per wallet must be greater than 0");
        require(config.rvfyDiscountBps <= maxRvfyDiscountBps, "Discount too high");

        saleConfigs[eventId] = config;

        emit SaleConfigured(
            eventId,
            config.price,
            config.maxSupply,
            config.saleStart,
            config.saleEnd,
            config.whitelistOnly
        );
    }

    /**
     * @dev Purchase tickets with ETH
     * @param eventId Event to purchase tickets for
     * @param quantity Number of tickets to purchase
     */
    function purchaseTickets(uint256 eventId, uint256 quantity) external payable nonReentrant {
        require(quantity > 0 && quantity <= 10, "Invalid quantity");

        uint256 gasStart = gasleft();
        _validatePurchase(eventId, quantity, msg.sender);

        SaleConfiguration storage config = saleConfigs[eventId];
        SaleMetrics storage metrics = saleMetrics[eventId];

        uint256 totalCost = config.price * quantity;
        require(msg.value >= totalCost, "Insufficient payment");

        // Process purchase
        uint256[] memory tokenIds = _processPurchase(eventId, msg.sender, quantity, totalCost, false);

        // Update metrics
        unchecked {
            metrics.totalSold += uint128(quantity);
            metrics.totalRevenue += uint128(totalCost);
            metrics.lastPurchaseTime = uint64(block.timestamp);

            // Check if this is a new purchaser
            if (purchaseHistory[eventId][msg.sender].purchaseTime == 0) {
                metrics.uniquePurchasers += 1;
            }
        }

        // Handle refund for overpayment
        if (msg.value > totalCost) {
            unchecked {
                uint256 refund = msg.value - totalCost;
                (bool success, ) = msg.sender.call{ value: refund }("");
                require(success, "Refund failed");
            }
        }

        uint256 gasUsed = gasStart - gasleft();
        emit TicketsPurchased(eventId, msg.sender, quantity, totalCost, false, tokenIds);

        // Gas optimization tracking
        if (gasUsed > 100000) {
            emit BatchPurchaseCompleted(msg.sender, _toArray(eventId), _toArray(quantity), totalCost, gasUsed);
        }
    }

    /**
     * @dev Purchase tickets with RVFY tokens (with discount)
     * @param eventId Event to purchase tickets for
     * @param quantity Number of tickets to purchase
     */
    function purchaseWithRVFY(uint256 eventId, uint256 quantity) external nonReentrant {
        require(quantity > 0 && quantity <= 10, "Invalid quantity");

        _validatePurchase(eventId, quantity, msg.sender);

        SaleConfiguration storage config = saleConfigs[eventId];
        SaleMetrics storage metrics = saleMetrics[eventId];

        // Calculate discounted price
        uint256 basePrice = config.price * quantity;
        uint256 discountedPrice;

        unchecked {
            discountedPrice = basePrice - (basePrice * config.rvfyDiscountBps) / 10000;
        }

        // Transfer RVFY tokens
        require(rovifyToken.transferFrom(msg.sender, treasury, discountedPrice), "RVFY transfer failed");

        // Process purchase
        uint256[] memory tokenIds = _processPurchase(eventId, msg.sender, quantity, discountedPrice, true);

        // Update metrics
        unchecked {
            metrics.totalSold += uint128(quantity);
            metrics.totalRevenue += uint128(basePrice); // Track full value for analytics
            metrics.lastPurchaseTime = uint64(block.timestamp);

            if (purchaseHistory[eventId][msg.sender].purchaseTime == 0) {
                metrics.uniquePurchasers += 1;
            }
        }

        emit TicketsPurchased(eventId, msg.sender, quantity, discountedPrice, true, tokenIds);
    }

    /**
     * @dev Batch purchase tickets for multiple events
     * @param eventIds Array of event IDs
     * @param quantities Array of ticket quantities
     */
    function batchPurchase(uint256[] calldata eventIds, uint256[] calldata quantities) external payable nonReentrant {
        require(eventIds.length == quantities.length, "Array mismatch");
        require(eventIds.length <= 5, "Batch too large");
        require(eventIds.length > 0, "Empty batch");

        uint256 gasStart = gasleft();
        uint256 totalCost = 0;

        // Calculate total cost
        for (uint256 i = 0; i < eventIds.length; ) {
            require(quantities[i] > 0 && quantities[i] <= 5, "Invalid quantity for batch");
            _validatePurchase(eventIds[i], quantities[i], msg.sender);

            unchecked {
                totalCost += saleConfigs[eventIds[i]].price * quantities[i];
                ++i;
            }
        }

        require(msg.value >= totalCost, "Insufficient payment");

        // Process all purchases
        for (uint256 i = 0; i < eventIds.length; ) {
            uint256 eventCost = saleConfigs[eventIds[i]].price * quantities[i];

            _processPurchase(eventIds[i], msg.sender, quantities[i], eventCost, false);

            unchecked {
                ++i;
            }
        }

        // Handle overpayment refund
        if (msg.value > totalCost) {
            unchecked {
                uint256 refund = msg.value - totalCost;
                (bool success, ) = msg.sender.call{ value: refund }("");
                require(success, "Refund failed");
            }
        }

        uint256 gasUsed = gasStart - gasleft();
        emit BatchPurchaseCompleted(msg.sender, eventIds, quantities, totalCost, gasUsed);
    }

    /**
     * @dev Add addresses to event whitelist
     * @param eventId Event ID
     * @param users Array of addresses to whitelist
     */
    function addToWhitelist(uint256 eventId, address[] calldata users) external onlyRole(SALES_MANAGER_ROLE) {
        require(users.length <= 100, "Batch too large");

        for (uint256 i = 0; i < users.length; ) {
            whitelists[eventId][users[i]] = true;
            unchecked {
                ++i;
            }
        }

        emit WhitelistUpdated(eventId, users, true);
    }

    /**
     * @dev Remove addresses from event whitelist
     * @param eventId Event ID
     * @param users Array of addresses to remove
     */
    function removeFromWhitelist(uint256 eventId, address[] calldata users) external onlyRole(SALES_MANAGER_ROLE) {
        require(users.length <= 100, "Batch too large");

        for (uint256 i = 0; i < users.length; ) {
            whitelists[eventId][users[i]] = false;
            unchecked {
                ++i;
            }
        }

        emit WhitelistUpdated(eventId, users, false);
    }

    /**
     * @dev Process refunds for cancelled events
     * @param eventId Event ID
     * @param buyers Array of buyer addresses to refund
     */
    function processRefunds(uint256 eventId, address[] calldata buyers) external onlyRole(TREASURY_ROLE) nonReentrant {
        require(buyers.length <= 50, "Batch too large");

        for (uint256 i = 0; i < buyers.length; ) {
            address buyer = buyers[i];
            PurchaseData memory purchase = purchaseHistory[eventId][buyer];

            if (purchase.amountPaid > 0 && !purchase.usedRVFY) {
                // Reset purchase data to prevent double refunds
                delete purchaseHistory[eventId][buyer];

                // Process ETH refund
                (bool success, ) = buyer.call{ value: purchase.amountPaid }("");
                if (success) {
                    emit RefundProcessed(eventId, buyer, purchase.amountPaid);
                }
            }

            unchecked {
                ++i;
            }
        }
    }

    /**
     * @dev Update sale status (activate/deactivate)
     * @param eventId Event ID
     * @param active New status
     */
    function setSaleStatus(uint256 eventId, bool active) external onlyRole(SALES_MANAGER_ROLE) {
        saleConfigs[eventId].active = active;
        emit SaleStatusChanged(eventId, active);
    }

    /**
     * @dev Withdraw accumulated platform fees
     */
    function withdrawPlatformFees() external onlyRole(TREASURY_ROLE) {
        uint256 amount = totalPlatformFees;
        totalPlatformFees = 0;

        (bool success, ) = treasury.call{ value: amount }("");
        require(success, "Fee withdrawal failed");
    }

    // INTERNAL FUNCTIONS

    function _validatePurchase(uint256 eventId, uint256 quantity, address buyer) internal view {
        SaleConfiguration memory config = saleConfigs[eventId];
        SaleMetrics memory metrics = saleMetrics[eventId];

        require(config.active, "Sale not active");
        require(block.timestamp >= config.saleStart, "Sale not started");
        require(block.timestamp <= config.saleEnd, "Sale ended");
        require(metrics.totalSold + quantity <= config.maxSupply, "Insufficient supply");

        // Check wallet limit
        uint256 currentPurchased = purchaseHistory[eventId][buyer].quantity;
        require(currentPurchased + quantity <= config.maxPerWallet, "Exceeds wallet limit");

        // Check whitelist if enabled
        if (config.whitelistOnly) {
            require(whitelists[eventId][buyer], "Not whitelisted");
        }

        // Anti-bot protection
        require(block.timestamp >= lastPurchaseTime[buyer] + minPurchaseInterval, "Purchase too soon");
    }

    function _processPurchase(
        uint256 eventId,
        address buyer,
        uint256 quantity,
        uint256 totalPaid,
        bool usedRVFY
    ) internal returns (uint256[] memory tokenIds) {
        // Update purchase history
        PurchaseData storage purchase = purchaseHistory[eventId][buyer];

        unchecked {
            purchase.amountPaid += uint128(totalPaid);
            purchase.quantity += uint32(quantity);
            purchase.purchaseTime = uint64(block.timestamp);
            purchase.usedRVFY = usedRVFY;
        }

        // Update rate limiting
        lastPurchaseTime[buyer] = block.timestamp;

        // Calculate platform fee and update tracking
        if (!usedRVFY) {
            unchecked {
                uint256 platformFee = (totalPaid * platformFeeBps) / 10000;
                totalPlatformFees += platformFee;
                eventRevenues[eventId] += totalPaid - platformFee;
            }
        }

        // Mint tickets (simplified - actual implementation would call TicketNFT)
        tokenIds = new uint256[](quantity);
        for (uint256 i = 0; i < quantity; ) {
            // tokenIds[i] = ticketNFT.mint(buyer, eventId);
            tokenIds[i] = i + 1; // Placeholder
            unchecked {
                ++i;
            }
        }

        return tokenIds;
    }

    function _toArray(uint256 value) internal pure returns (uint256[] memory) {
        uint256[] memory array = new uint256[](1);
        array[0] = value;
        return array;
    }

    // VIEW FUNCTIONS

    /**
     * @dev Get sale configuration for an event
     * @param eventId Event ID
     * @return Sale configuration struct
     */
    function getSaleConfig(uint256 eventId) external view returns (SaleConfiguration memory) {
        return saleConfigs[eventId];
    }

    /**
     * @dev Get sale metrics for an event
     * @param eventId Event ID
     * @return Sale metrics struct
     */
    function getSaleMetrics(uint256 eventId) external view returns (SaleMetrics memory) {
        return saleMetrics[eventId];
    }

    /**
     * @dev Get purchase history for a buyer
     * @param eventId Event ID
     * @param buyer Buyer address
     * @return Purchase data struct
     */
    function getPurchaseHistory(uint256 eventId, address buyer) external view returns (PurchaseData memory) {
        return purchaseHistory[eventId][buyer];
    }

    /**
     * @dev Check if address is whitelisted for an event
     * @param eventId Event ID
     * @param user User address
     * @return True if whitelisted
     */
    function isWhitelisted(uint256 eventId, address user) external view returns (bool) {
        return whitelists[eventId][user];
    }

    /**
     * @dev Calculate discounted price for RVFY payment
     * @param eventId Event ID
     * @param quantity Number of tickets
     * @return discountedPrice Price after RVFY discount
     * @return savings Amount saved
     */
    function calculateRVFYDiscount(
        uint256 eventId,
        uint256 quantity
    ) external view returns (uint256 discountedPrice, uint256 savings) {
        SaleConfiguration memory config = saleConfigs[eventId];
        uint256 basePrice = config.price * quantity;

        unchecked {
            savings = (basePrice * config.rvfyDiscountBps) / 10000;
            discountedPrice = basePrice - savings;
        }
    }

    /**
     * @dev Get remaining ticket supply for an event
     * @param eventId Event ID
     * @return remaining Number of tickets remaining
     */
    function getRemainingSupply(uint256 eventId) external view returns (uint256 remaining) {
        SaleConfiguration memory config = saleConfigs[eventId];
        SaleMetrics memory metrics = saleMetrics[eventId];

        unchecked {
            remaining = config.maxSupply - metrics.totalSold;
        }
    }
}
